-- GENERATED by `wfi generate` from data/quest/quest-0002.jsonl. Do not edit: `wfi validate` regenerates and diffs it.
local _, WFI = ...
WFI.Data.add("quest", {
  [2038] = { "Gli attrezzi perduti di Bingles", "Trova e riporta gli attrezzi di Bingles:\n\nBingles' Wrench, Bingles' Screwdriver, Bingles' Hammer e Bingles' Blastencapper.", "Come se schiantarmi nel Loch non bastasse, i trogg dell'isola qui vicino mi hanno attaccato e mi hanno rubato gli attrezzi e gli speciali esplosivi Blastenheimer Blastencapper. Senza girocottero e senza esplosivi, il movimento non ha speranze!\n\nRecupera i miei attrezzi e trova i miei esplosivi Blastencapper, {name}. Per Gnomeregan!", "{name}! Dove sono le mie cose?!", "Hai reso un grande servizio al movimento, {name}. I trogg e i leper gnome che infestano Gnomeregan sentiranno presto il peso di un assalto aereo gnomesco!", 0xf9774368, 0x792008cf, 0xd09399c8, 0x1dd7bb2d, 0x5ee96793, "....." },
  [2039] = { "Trova Bingles", "Trova Bingles Blastenheimer a Loch Modan.", "Abbiamo perso i contatti con Bingles! È stato mandato in ricognizione sopra Gnomeregan e non fa rapporto da più di una settimana. Me lo sento che è andato a farsi saltare in aria.\n\nÈ stato visto l'ultima volta mentre sorvolava il Loch. Forse puoi indagare tu, {name}.", nil, "Quindi Gnoarn non si fida delle mie capacità di ricognizione? Chissà perché...\n\nLascia perdere, ho bisogno del tuo aiuto! Anzi no! Il movimento ha bisogno del tuo aiuto!", 0x615905ca, 0x3376ba72, 0x0eb9eb85, nil, 0xe10b4d25, "...m." },
  [2040] = { "Assalto sotterraneo", "Recupera il Gnoam Sprecklesprocket dalle Deadmines e riportalo a Shoni the Shilent, a Stormwind.", "Gnomeregan è caduta sotto il controllo di quei malvagi trogg! La situazione è grave, ma forse puoi aiutare, {name}.\n\nNel profondo delle Deadmines c'è uno shredder goblin funzionante. Trova quello shredder e riporta l'alimentatore intatto. Con l'alimentatore dello shredder potremo dare ai nostri gyrodrillmatic excavationator l'energia necessaria per sfondare i confini rocciosi sotterranei di Gnomeregan, aprendo la strada a un assalto gnomesco!", "Hai trovato il Gnoam Sprecklesprocket, {name}?", "Ben fatto, {name}. Grazie a te, Gnomeregan è un passo più vicina al giorno della sua liberazione!", 0x80a0cba5, 0xea953ef0, 0x63b95920, 0x9b272279, 0x733d0acf, "....." },
  [2041] = { "Parla con Shoni", "Parla con Shoni the Shilent, a Stormwind.", "Forse... forse puoi aiutarci nella battaglia per Gnomeregan.\n\nA Stormwind troverai il comandante della nostra squadra d'assalto sotterranea, Shoni the Shilent. A Shoni serve aiuto con le sue girotrivellatrici escavatorie.\n\nProbabilmente la troverai tra i nani di Stormwind.\n\nBuona fortuna, {name}.", nil, "Porti notizie dal comando centrale?", 0xf9384378, 0xe35660ac, 0xa17f2e67, nil, 0xc9cd2431, "...m." },
  [2078] = { "La vendetta di Gyromast", "Trova il primo ufficiale di Gelkak, il Threshwackonator 4100, e riportalo da Gelkak.", "Marinaio d'acqua dolce, devi trovare il mio primo ufficiale.\n\nPrendi 'sta chiave, infilagliela nella zucca e riportalo qui a servire il capitano.\n\nQuei murloc e il loro capo non saranno troppo contenti quando il mio primo ufficiale li acchiapperà!", "Dov'è il mio primo ufficiale, {name}? Catene e squali per te, se non ti sbrighi!", "Yarrr... Stai dimostrando di essere più di un lupo di mare codardo, marinaio d'acqua dolce.\n\nIl Cap'n potrebbe promuoverti a mozzo del ponte di poppa se continui così...", 0xd9963931, 0xd2b23f5c, 0x7ec45f79, 0x4a2ccf6d, 0xa5444273, "....." },
  [2098] = { "Il recupero di Gyromast", "Trova e riporta a Gelkak Gyromast i tre pezzi della Gelkak's Key.", "La vita del pirata non è facile, marinaio d'acqua dolce. Non è tutto saccheggi e alcol! Ahimè, la mia nave è affondata proprio al largo per colpa di quei maledetti Threshadons.\n\nQuello che mi serve è il mio primo ufficiale di nuovo funzionante!\n\nQuando sono finito sulla riva, la chiave del mio primo ufficiale si è rotta sugli scogli ed è stata rubata dalle bestiacce di Darkshore. Con la coda dell'occhio ho visto alcuni di quei Ragin' Crawlers, Ferocious Foreststrider e murloc frugare tra i rottami....", "Hai trovato la mia chiave rotta, marinaio d'acqua dolce?", "Ohilà, lupo di mare scorbutico! Ce l'hai fatta! Presto il mio primo ufficiale tornerà in funzione e quelle bestiacce non sapranno cosa le ha colpite!\n\nMmm, hai visto il mio primo ufficiale?", 0xfb8edee7, 0xb52c5a6e, 0x1f7e89e6, 0x5badcb40, 0x8453295d, "....." },
  [2118] = { "Terre appestate", "Cattura un Rabid Thistle Bear vivo e portalo da Tharnariun.\n\nSe non riesci a catturare un Rabid Thistle Bear e perdi la trappola, torna da Tharnariun Treetender e chiedine un'altra.", "Un morbo si diffonde su Darkshore, e afferra la mente e il corpo di tutto ciò che tocca.\n\nI thistle bear sono i più colpiti da questa piaga. Bestie un tempo nobili ora sono strumenti di distruzione, rabbiose e frenetiche. Forse ho una cura per questo male.\n\nPorta questa trappola nella foresta e posala a terra. Qualunque Rabid Thistle Bear attraversi la luce diventerà docile per un breve tempo. Quando l'orso sarà docile, ti seguirà. Riportalo qui, {name}.", "Mi hai portato l'animale malato, {name}?\n\nSe non riesci a far scattare la trappola, non preoccuparti: Tharnariun's Hope è eterna. Se ti serve un'altra trappola, abbandona il tuo compito e torna da me.", "Il nostro lavoro è appena cominciato, {name}. Sei <pronto/pronta> per il tuo prossimo compito?", 0xfa0a3a70, 0x3807aa6c, 0xe76e9858, 0xcaf47f66, 0xb17abac8, "....." },
  [2138] = { "Purificare gli infetti", "Libera la foresta da 20 Rabid Thistle Bears e torna da Tharnariun Treetender, a Darkshore.", "Come temevo, la cura non funziona.\n\nMi rattrista molto ordinare la morte di qualunque bestia della natura, ma i thistle bear malati e contaminati vanno abbattuti.\n\nTorna nella foresta e distruggi 20 Rabid Thistle Bears, {name}. Di certo non fermerà la piaga, ma rallenterà per un po' i danni che gli animali fanno alla nostra foresta e ai suoi abitanti.", "Il tuo compito è concluso?", "Hai reso un grande servizio ad Auberdine, {name}, ma il tuo compito non è ancora concluso.\n\nTorna da me quando ti sarai <riposato/riposata>.\n\n...e {name}, prepara la mente e l'anima a nuovo spargimento di sangue.", 0x6f6f3496, 0x02dfdd6a, 0x7195c76b, 0x79783cba, 0x6c182eed, "....." },
  [2139] = { nil, "Trova e uccidi la Den Mother.", "La sopravvivenza del nostro popolo e delle nostre terre ha un prezzo doloroso, {name}.\n\nHai versato il sangue dei servitori della natura; hai abbattuto molti animali malati. La gente di Auberdine ti è debitrice, perché il dolore della foresta si è attenuato, anche se solo per un momento.\n\nHo un ultimo compito per te, ma ti avverto: dovrai uccidere ancora. Spero che sia l'ultima volta che ti chiamo, {name}.\n\nIn una caverna a nord-est, vicino a Bashal'Aran, vive la Den Mother. Uccidila.", "Con la Den Mother infetta uccisa, il numero di Rabid Thistle Bear che entrano nelle nostre terre è diminuito. Non perdere tempo, {name}.", "Hai combattuto per Auberdine con coraggio e onore, {name}. Nelle nostre terre dilaniate dalla guerra, morte e disperazione sono comuni. Molti non sapranno affrontare la sfida della vita nella nostra nuova casa e sceglieranno invece di nascondersi nelle loro dimore o di fuggire nelle terre più fortificate dell'Alliance.\n\nGrazie, {name}. Forse un giorno, presto, combatteremo fianco a fianco come compagni contro un altro nemico.", nil, 0x4766c644, 0xe4256bfb, 0x3c698219, 0x8e54a76e, "m...." },
  [2158] = { "Riposo e svago", "Parla con Innkeeper Farley, al Lion's Pride Inn.", "Ogni avventuriero dovrebbe riposare quando la stanchezza si fa sentire, e non c'è posto migliore per riposarsi e svagarsi del Lion's Pride Inn!\n\nIl mio migliore amico, Innkeeper Farley, gestisce il Lion's Pride. Se gli dici che ti mando io, potrebbe farti i prezzi speciali scontati su cibo e bevande.\n\nPer trovare il Lion's Pride Inn, segui la strada verso sud da qui: non puoi sbagliare!", nil, "Riposo e svago per chi è stanco e infreddolito: è il nostro motto! Prego, siediti accanto al fuoco e fai riposare le tue ossa stanche.\n\nTi va di assaggiare un po' del nostro ottimo cibo e delle nostre bevande?", 0xf6b2744d, 0xf61951e2, 0xff0677e6, nil, 0x6e2b261e, "...m." },
  [2159] = { "Una consegna per Dolanaar", "Porta la Dolanaar Delivery a Innkeeper Keldamyr.", "Salute, giovane {class}. Puoi aiutarmi? Ho un pacco di erbe da consegnare al paese di Dolanaar. Ma ho ancora affari con i druidi di Shadowglen e non posso ancora partire.\n\nPuoi consegnare tu questo pacco? Va dato a Innkeeper Keldamyr, alla locanda di Dolanaar. Si trova lungo la strada, a sud.", "Come posso esserti utile, giovane? Sei qui per riposare alla locanda? Ti serve una pietra del ritorno?", "Ah sì, la consegna di erbe da Shadowglen. Peccato che Porthannius non abbia potuto portarla di persona, perché abbiamo molto di cui parlare, lui e io. Ma sono comunque felice di avere le erbe, e sono felice che tu sia <venuto/venuta>.\n\nGià che sei qui, ti prego, riposati. Gli eroi devono mantenere alti la forza e lo spirito, e devono trovare riposo e conforto ogni volta che possono. Perché trascurare la pace del corpo e della mente è una via sicura verso il fallimento.\n\nQuindi... riposa.", 0x1821b05c, 0x63d50e5c, 0xc4d46c8a, 0x4944e9aa, 0x1a7ac861, "....." },
  [2160] = { "Rifornimenti per Tannok", "Consegna la Crate of Inn Supplies a Tannok Frosthammer, a Kharanos.", "Ehi! Hai l'aria di chi è avvezzo alle avventure, e pure <robusto/robusta>. Se hai intenzione di sfidare il passo, potresti portare un pacco alla locanda di Kharanos?\n\nAvevi intenzione di fermarti alla locanda, giusto? Se superi il passo, vorrai di sicuro riprendere fiato lì.\n\nComunque, porta questo a Tannok Frosthammer, l'aiutante del locandiere. Io non posso attraversare il passo, e ci vorranno giorni prima che passi una scorta di Mountaineer!", "Salve! Entra, siediti accanto al fuoco e scaldati con un boccale di birra.", "Ah, finalmente, le provviste da Hands! Cominciavo a preoccuparmi: abbiamo avuto poche notizie da Anvilmar da quando i trogg hanno invaso il passo.\n\nGrazie per avermelo portato, {name}. E ti prego, mettiti <comodo/comoda>. Sarai <stanco/stanca> dopo il viaggio.", 0x1a599de9, 0xec5c9fbf, 0x3e311c16, 0xd1d47487, 0xe882bc33, "....." },
  [2178] = { "Vivere di strider", "Riporta 5 Strider Meat ad Alanndarian Nightsong, ad Auberdine.", "Senti questo profumo delizioso? È la mia ricetta segreta, {name}: stufato di strider fresco. Delizioso!\n\nForse ti interesserebbe imparare la ricetta?\n\nPrima di insegnartela, dovrai dimostrare di saper gestire quelle bestie.\n\nOra, non pretendo che tu ne vada a domare uno e me lo riporti in groppa, ma se riesci a ucciderne qualcuno e a riportarmi un po' della loro carne succulenta, potrei lasciarmi convincere a svelarti i segreti dello stufato di strider.", "La pentola è vuota e ho fame! Perché ci metti tanto?", "Fantastico! Assaggialo e dimmi cosa ne pensi, {name}!", 0xfb77df5a, 0xccc0962f, 0x0abb668a, 0xe34f9c3e, 0x42580f7f, "....." },
  [2198] = { "La collana in frantumi", "Cerca chi ha creato la collana in frantumi per scoprirne il possibile valore.", "Hai trovato una collana ossidata, anche se l'ossidazione nasconde una lavorazione intricata e magica. La collana è in frantumi: alla montatura sembrano mancare tre gemme. Sul retro della collana c'è la debole impronta del sigillo cittadino di Ironforge. Sotto il sigillo sono incise tre minuscole lettere: \"TdK\".\n\nSe c'è qualcosa da scoprire dalla collana, dovrai conoscerne le origini. Forse il sigillo e le iniziali sono un punto di partenza...", "Hai sbagliato gnomo, amico! Io non c'ero! Non puoi provare niente!\n\nAspetta un attimo... chi sei? Ma che... dove hai trovato questa collana?", "Sì... sono io il gioielliere che ha creato questa collana. Ma non sono nel ramo di regalare informazioni come se fossero gratis. Le informazioni non sono mai gratis, amico. Se devo aiutarti, prima devi aiutare ME.", 0xb1327827, 0xeeb9407b, 0xb9a1fb6d, 0x0b9a539d, 0x82358beb, "....." },
  [2199] = { "Sapere a caro prezzo", "Porta cinque lingotti d'argento a Talvash del Kissel, a Ironforge.", "Sono un gioielliere di gran fama qui a Ironforge! Be', di passata fama, almeno... Sono caduto in disgrazia per gli imbrogli di un concorrente! In questo mestiere una cattiva reputazione significa la rovina finanziaria. Di conseguenza mi ritrovo senza un rame, con il mio buon nome, al momento infangato.\n\nVoglio che tu mi procuri cinque lingotti d'argento per completare un ordine che ho ricevuto: il primo da quella che sembra un'eternità.\n\nPortami quei cinque lingotti d'argento e risponderò alle tue domande sulla collana.", "Hai i cinque lingotti d'argento che ti ho chiesto? Ti racconterò la mia triste storia di sventure sulla collana che ora possiedi... ma solo dopo aver avuto quei lingotti! Ti prego, aiuta uno gnomo, eh?", "Per me sei a posto; non m'importa cosa dicono gli altri... scherzo, scherzo! Davvero, grazie amico mio.\n\nDunque, la collana che hai è una delle mie creazioni migliori, ma le mancano tre gemme che servono a legarle il potere magico. L'ho creata tempo fa per un paladino. Si era autoproclamato in missione per ripulire la \"corruzione malvagia\" presente in un sito di scavo nelle Badlands chiamato Uldaman.\n\nBe'... quel paladino è morto a Uldaman, e quello è stato solo l'inizio dei miei guai.", 0x99934f46, 0x01df1a41, 0xf6b25bc5, 0x5573d0cc, 0x592dece0, "....." },
  [2200] = { "Ritorno a Uldaman", "Cerca indizi a Uldaman su dove si trovi ora la collana di Talvash. Il paladino ucciso di cui parlava è stato l'ultimo ad averla.", "Un mio concorrente ha messo in giro la voce che la mia collana ha maledetto il paladino. Inutile dire che nessuno vuole comprare oggetti maledetti da un gioielliere.\n\n{name}, ti propongo un affare: trova le gemme e io rimetterò insieme la collana, a patto che tu faccia sapere in giro che io non creo oggetti maledetti!\n\nProva a cercare indizi a Uldaman; magari vedi se il corpo del paladino è laggiù, visto che sappiamo che è stato lui l'ultimo ad averla! Quando trovi le gemme, usa questa: ti permetterà di contattarmi qui a Ironforge.", nil, "Resti di un paladino: leggendo il diario scopri che, dopo molti sforzi, il paladino aveva individuato la posizione di tutte e tre le gemme mancanti.\n\nI nani Shadowforge hanno nascosto il rubino nella loro zona barricata mentre combattevano i trogg per il controllo di Uldaman.\n\nI trogg hanno nascosto il topazio in un'urna vicino ad alcuni insoliti abitanti di Uldaman: nani dell'Alleanza!\n\nInfine, l'anziano dei trogg in persona si è preso lo zaffiro.", 0x0a4fff55, 0x2968a0a2, 0x8111f254, nil, 0x4fa0e3d8, "...m." },
  [2201] = { "Trova le gemme", "Trova il rubino, lo zaffiro e il topazio sparsi per Uldaman. Una volta ottenuti, contatta Talvash del Kissel a distanza usando la Phial of Scrying che ti ha dato.\n\nDal diario sai che...\n\n* Il rubino è stato nascosto in una zona barricata degli Shadowforge.\n\n* Il topazio è stato nascosto in un'urna in una delle zone dei trogg, vicino ad alcuni nani dell'Alleanza.\n\n* Lo zaffiro se l'è preso Grimlok, il capo dei trogg.", "Il diario del paladino ha fornito forse gli unici indizi che Uldaman offrirà sulla posizione delle gemme della collana. Se gli scritti del paladino sono ancora attendibili, bisognerà occuparsi dei nani Shadowforge e dei trogg che si contendono il sito di scavo.\n\nForte di queste informazioni, la ricerca delle gemme comincia sul serio. Quando avrai tutte le gemme, dovrai avvisare Talvash, a Ironforge, tramite la Phial of Scrying, come da sue istruzioni.", "L'immagine di Talvash prende forma nelle acque della coppa divinatoria.\n\n\"Wow, sei ancora vivo! Sei riuscito a trovare le gemme? Sei davvero il salvatore della mia reputazione che speravo? Ti prego, dimmi che non hai sprecato una carica della fiala solo per chiacchierare: quelle cose non costano poco, e sono già in gravi ristrettezze economiche.", "Sì, sono proprio le tre gemme. Ottimo lavoro! Purtroppo il tuo lavoro non è ancora del tutto finito.\n\nNo, non sto cercando di fregarti, {class} <sciocco/sciocca>. Qui si tratta di creare gioielli magici, gioielli del livello di Talvash del Kissel! Serve una fonte di energia potente per dargli un po' di grinta. Be', quella collana non ha più grinta da dare.", 0xb51d5b0d, 0xf4b144bc, 0x4c6f3add, 0x60210ab2, 0x8762b2b9, "....." },
  [2202] = { "Reagenti da Uldaman", nil, "Ho sentito parlare di una pianta scoperta da poco, le Magenta Fungus Caps. Crescono a grappoli, in fondo al sito di scavo di Uldaman; forse ci sono anche altrove, ma per ora è l'unico posto che conosco. Voglio studiarne il possibile uso in alchimia, ed è qui che entri in gioco tu.\n\nTrova i grappoli di funghi magenta e portamene una dozzina. Attenzione: se scossi, i grappoli possono sputare spore velenose.\n\nFallo per me e ti preparerò una partita di uno dei miei famosi elisir ricostituenti!", "Hai ottenuto le Magenta Fungus Caps che mi servono per il mio lavoro alchemico? Niente funghi, niente ricompensa!", nil, 0xec9c87f2, nil, 0xf40372d4, 0x3dc33ca7, nil, ".m..m" },
  [2203] = { "Reagenti dalle Badlands II", nil, nil, "Hai usato i recipienti per procurarmi il sangue di scorched guardian dragon che mi serve? Sì, lo so che è un compito pericoloso... ma la ricetta del mio intruglio ricostituente aspetta il tuo successo. Rischio e ricompensa, amico mio... rischio e ricompensa...", nil, 0x883768bc, nil, nil, 0x0cf00f74, nil, ".mm.m" },
  [2204] = { "Restaurare la collana", "Ottieni una fonte di energia dal costrutto più potente che riesci a trovare a Uldaman e consegnala a Talvash del Kissel, a Ironforge.", "Dovrai trovare un po' di \"grinta\" per la collana, e Uldaman è probabilmente il posto migliore per trovarla, in effetti. Immagino che là dentro ci siano un sacco di costrutti in giro, no? Be', abbatti il costrutto più grosso e cattivo di quel posto e prendi la sua fonte di energia! Sono quasi sicuro di poterla fondere nella collana.\n\nSenza quella fonte di energia, riparare la collana sarà impossibile. Torna da me qui a Ironforge quando ce l'hai, e te la sistemeremo per bene!", "Non ti sei nemmeno <fermato/fermata> a darti una sistemata dopo aver lasciato Uldaman, vero? Sei <venuto/venuta> <dritto/dritta> qui, al diavolo l'odore di sotterraneo che ti porti dietro. Be', speriamo che questa visita sia solo maleodorante, e non pure inutile.\n\nHai la fonte di energia per la collana?", "Ma guarda: sono proprio contento di vedere te e questa fonte di energia tutti interi. Mi ci vorrà un momento per fondere magicamente la fonte di energia con la collana, ora che le gemme sono di nuovo al loro posto. Una volta fatto, però, la collana sarà tua!\n\nSei <emozionato/emozionata>, vero? <Tutto/Tutta> fremente d'attesa? Ora, dove ho messo quel focalizzatore di incantesimi...", 0xd9740d79, 0xa02feecf, 0x905848a6, 0xc5dc9fc2, 0xf81ff10a, "....." },
  [2205] = { "Cercare lo SI: 7", "Consegna il pacco di Keryn Sylvius a Master Mathias Shaw, alle Stormwind Barracks.", "Il distintivo? Oh, non è niente, pivello: niente che tu possa gestire, comunque. A guardarti, direi che Mathias ti scambierà per <il/la> <ragazzo/ragazza> che consegna il formaggio, invece che per <un/una> <vero/vera> <ladro/ladra>. Comunque sia, mi hanno affidato un lavoro e ho promesso di portarlo a termine.\n\nA proposito, consegna questo pacco a Mathias e forse ti darà un compitino o due.\n\nDatti una mossa.", "Posso aiutarti, {class}?", "Mi hai trovato. E a guardarti, direi che la corsa e la ricerca che ne è seguita ti hanno messo a dura prova, sia nella mente sia nel corpo.\n\nVuoi che Renzik ti indichi la strada per una locanda, o sei <pronto/pronta> per un po' di lavoro?", 0xcaa7a9f9, 0x07f738a1, 0xfb528bff, 0x01686e7d, 0xde7424bd, ".....", nil, nil, 0x454725db, nil, nil },
  [2206] = { "Arraffa e scappa", "Trova il Defias Dockmaster e recupera lo Shipping Schedule per il Master Mathias Shaw.", "I nostri agenti sul campo segnalano un'intensa attività dei Defias a sud di Goldshire. I rapporti indicano che i Defias si sono impadroniti del Jerod's Landing e ora lo usano per contrabbandare grandi quantità di merce da Redridge a Westfall.\n\nHo bisogno che ti infiltri nella casa del molo e mi procuri quell'orario delle spedizioni, {name}. Probabilmente lo troverai sepolto nelle tasche del Dockmaster.\n\n...e {name}, se dovessi essere <scoperto/scoperta>, lo SI:7 negherà di sapere della tua esistenza.", "La tua mortalità si consuma a ogni istante che sprechi a bighellonare nelle caserme, {class}.", "Sono sbalordito... Sbalordito che Keryn abbia finalmente trovato una recluta che potrebbe avere la stoffa di <un/una> <vero/vera> <ladro/ladra>. Prendi questa lama, {name}. Verrà un giorno in cui sarai <chiamato/chiamata> di nuovo a servire lo SI:7. Affina le tue capacità, tieni gli occhi aperti e quella lama affilata.\n\nNon ci vedrai arrivare, ma lo sentirai quando saremo lì...", 0x1787987c, 0x494cbf92, 0xb285531c, 0xcd220e78, 0x0bc8224c, "....." },
  [2218] = { "La via della salvezza", "Parla con Hulfdan Blackbeard, a Ironforge.", "Un'altra anima persa in cerca di una guida, eh? Immagino tu voglia trovare uno scopo, il tuo scopo. L'ho visto mille volte: un altro eroe in cerca di lavoro.\n\nBeh, oggi è il tuo giorno fortunato, amico. Hogral ha la cura per il tuo male.\n\nEcco cosa devi fare: prendi questa strada fino a Ironforge e raggiungi la Forlorn Cavern. Lì trova la gilda dei ladri e parla con Hulfdan Blackbeard. Ti metterà sulla via della salvezza.", nil, "Allora pensi di essere una vera canaglia? Sei <destinato/destinata> a essere tra i pochi eletti di Blackbeard, un ufficiale dell'Hidden Circle?\n\nSolo un furfante buono a nulla avrebbe un'opinione così alta di sé.\n\nÈ proprio quel che cerchiamo! <Benvenuto/Benvenuta> a bordo, {name}!", 0x7deeb917, 0xc16240a1, 0x238604cf, nil, 0x3b3483ab, "...m." },
  [2238] = { "Un sotterfugio semplice", "Trova Onin MacHammar vicino a Gnomeregan.", "Vedi, il re sta sfruttando la cava fino all'osso per minerali e gemme. Più ricchezze di quante un nano dovrebbe vederne in dieci vite.\n\nL'Hidden Circle ha dei valori, {name}. Noi diamo valore agli oggetti di valore. Capisci?\n\nOra, noi pensiamo che il re dovrebbe dividere un po' di quel bottino, ma non vogliamo che il vecchio \"Barbafetida\" sappia che lo sta dividendo... se capisci cosa intendo.\n\nDevi parlare con Onin MacHammar, laggiù vicino a Gnomeregan, e riportarci un rapporto. Quel nano furbo si è nascosto tra i lebbrosi. Fai attenzione.", nil, "Sssst! Abbassa la voce, sciocco. Ci sentiranno.", 0xc34a099a, 0xba2a3a79, 0xad153087, nil, 0xab2bb692, "...m." },
  [2239] = { nil, "Riporta l'Onin's Report a Hulfdan, a Ironforge.", "La cava? Sì, vedo passare quei mostruosi carri a vapore corazzati da questo posto quasi ogni giorno.\n\nI miei contatti a est mi dicono che il carro parte da Ironforge, fa un carico alla Gol'Bolar Quarry, si ferma a Kharanos per rifornirsi e poi, per qualche maledetto motivo, fa il giro lungo passando per Gnomeregan, prima di raggiungere Ironforge per scaricare la merce.\n\nÈ tutto nel rapporto, {race}. Riportalo a Hulfdan, così potrà pianificare la prossima mossa.", "Ti è piaciuto il fetore di gnomo lebbroso? Te lo chiedo solo perché hai un sorriso folle stampato in faccia.\n\nChe notizie porti da Onin?", "Il giro lungo? Per la mia barba!\n\nHai fatto bene, {name}. Prendi questo pugnale e sparisci. Il Circle ti chiamerà di nuovo quando il passo tre sarà pronto per essere messo in atto.\n\nQual è il passo tre? Viene subito dopo il passo due: io che ti do un calcio nel sedere.\n\n<Interessato/Interessata>?", nil, 0xb2b73a1a, 0x6d453b17, 0x7416d656, 0x6c9c93b3, "m...." },
  [2240] = { "La camera nascosta", "Leggi il diario di Baelog, esplora la camera nascosta, poi fai rapporto al Prospector Stormpike.", "Ora, veniamo al compito.\n\nC'è una camera segreta, la Chamber of Khaz'mul, che va esplorata. Il problema è che la camera si trova dietro un'enorme porta chiusa a chiave! Per fortuna io so come aprirla.\n\nHo descritto tutto nel mio diario, qui sul tavolo. Io e la mia banda per ora siamo bloccati qui... quindi tu, {name}, devi trovare la camera di Khaz'mul per noi!\n\nLeggi il mio diario, esplora la camera, poi fai rapporto al Prospector Stormpike all'Explorers' League di Ironforge.", "Hai qualcosa da riferire?", "Hai visto la Chamber of Khaz'mul? Straordinario! Baelog era sicuro che esistesse, ma devo ammettere che avevo i miei dubbi.\n\nGrazie, {name}. Con un po' di fortuna la tua scoperta spingerà i nostri capi a rinnovare gli sforzi per riprendere Uldaman. E se tornerà mai sotto il controllo di Ironforge, i segreti della Chamber of Khaz'mul saranno nostri!", 0x715ec1d2, 0x426bb2d5, 0xd19acc6b, 0x0c101615, 0x1bbdd389, "....." },
  [2241] = { "La mela cade", "Porta la Jannok's Rose a Syurna, a Darnassus.", "Dicono che sono 'cotto', qualunque cosa voglia dire.\n\nCerto, passo ogni momento da sveglio a pensare a Syurna. Certo, la mia casa è piena di quadri e disegni di Syurna. Certo, spesso passo giorni senza mangiare, dormire o bere, mentre piango l'amore che avremmo potuto avere. È così sbagliato?\n\nOra non vuole vedermi! ME! Ho provato a mandarle messaggi, ma non parla nemmeno con nessuno che non sia un ladro.\n\nPotresti consegnarle questo fiore? Non dimenticare di dirle che viene da Jannok.", "Oh, ma che meraviglia. Hai portato i fiori per il tuo funerale.", "Se avessi conservato ogni fiore che quel babbeo di Jannok mi ha mandato, avrei avuto di che aprire una bottega. Comunque, sembra che l'ultimo corriere di Jannok possa rivelarsi utile.\n\nTi interessa un lavoro, {class}?", 0x1e34b4e5, 0x539618ee, 0xb5594b87, 0x9279e6d4, 0x640f88b7, "....." },
  [2242] = { "Il destino chiama", "Trova Sethir the Ancient e riporta a Syurna qualunque indizio tu scopra.", "Crediamo che ci sia un essere che potrebbe aiutarci a capire cosa sta succedendo alle foreste di Teldrassil. Purtroppo convincere quella creatura a collaborare si è rivelato disastroso.\n\nSi nasconde su un ramo ai margini dell'Oracle Glade. Tutti quelli che finora si sono avvicinati al satiro, con la forza o con la diplomazia, sono andati incontro alla rovina. Forse la furtività è la risposta, {name}.\n\nScopri cosa porta Sethir the Ancient nelle sue sacche e torna a riferirmelo.", "Hai qualcosa da riferire su Sethir the Ancient, {name}?", "Sono notizie cupe, {name}. Sembra che il morbo che ha colpito le foreste e i fiumi di Darkshore abbia cominciato a contaminare la nostra casa.\n\nCi hai servito bene, ma non c'è altro che tu possa fare qui. Prendi questa lama come ricompensa per il tuo servizio a Teldrassil.", 0x8c35f2ae, 0xe9faceef, 0xccf34b01, 0x274bca56, 0x1dda5b8b, "....." },
  [2258] = { "Reagenti dalle Badlands", nil, nil, "Hai già le cose che mi servono? Non sarai <pagato/pagata> finché non mi porti quei reagenti.", nil, 0xaca0069d, nil, nil, 0x5be9782d, nil, ".mm.m" },
  [2259] = { nil, "Mettiti in contatto con Erion Shadewhisper, a Darnassus.", "Non preoccuparti, {name}, non ti mando da Syurna. Erion ha bisogno di te al Cenarion Enclave. Sbrigati!", nil, "È ora di allargare i tuoi orizzonti, {race}: il mondo ti aspetta.", nil, 0x1eb27f12, 0x7bffcd48, nil, 0x1d5a0e27, "m..m." },
  [2260] = { "La richiesta di Erion", "Vai a Stormwind City e chiedi consiglio a Renzik \"The Shiv.\"", "La voce delle tue imprese si è sparsa in lungo e in largo, {name}. Così lontano, anzi, che lo Stormwind Intelligence ha chiesto di te per nome.\n\nIl viaggio è faticoso e non privo di pericoli, ma l'occasione di addestrarsi con lo SI:7 non va presa alla leggera.\n\nUn nuovo mondo ti attende, {name}. Raggiungi la Old Town di Stormwind e parla con Renzik \"The Shiv\" al quartier generale dello SI:7.", nil, "Hai risposto alla chiamata dello SI:7, {name}, e hai viaggiato da coste lontane per unirti a noi, ma hai ancora molto da imparare.", 0x01bdb2d2, 0x370fd4f0, 0x6d9f7c62, nil, 0xd5283d8b, "...m." },
  [2278] = { "I dischi di platino", nil, nil, nil, nil, 0xd5650943, nil, nil, nil, nil, ".mmmm" },
  [2279] = { "I dischi di platino", "Porta la versione in miniatura dei Discs of Norgannon all'Explorers' League di Ironforge.", "Toccare di nuovo i Discs of Norgannon ti fa formicolare la mano. Questa volta, però, si sente uno strano stridore provenire dall'interno dei dischi.\n\nIl tuo zaino diventa all'improvviso più pesante di prima. Dentro scopri una versione in miniatura dei dischi!\n\nSenza dubbio un oggetto del genere sarebbe preziosissimo per chi si interessa alla storia antica di Azeroth. L'Explorers' League di Ironforge è un gruppo del genere, noto in tutta l'Alleanza: forse potrebbero farne buon uso.", "Sì, posso aiutarti in qualcosa? Ti assicuro che al momento sono molto impegnato. Ma se si tratta di qualcosa di grave importanza per l'Explorers' League, sono tutt'orecchi!", "Cosa hai lì... oh cielo. Dove l'hai trovato?\n\nNo, davvero?\n\nHai parlato con chi di cosa?\n\nNo, davvero?!\n\n<Mio/Mia> <caro/cara> {class}, potresti aver appena fatto la scoperta archeologica dell'anno! Per gli dei, ma chi voglio prendere in giro, la scoperta del secolo! Se questi dischi sono ciò che penso, potrebbero essere proprio la chiave che cercavamo! Potrebbero dimostrare una volta per tutte la legittimità della creazione incantata dei nani!", 0xd5650943, 0x7540c2d4, 0x73154522, 0x7f85817c, 0xac58b5d8, "....." },
  [2280] = { "I dischi di platino", nil, nil, nil, nil, 0xd5650943, nil, nil, nil, nil, ".mmmm" },
  [2281] = { "Appuntamento a Redridge", "Avventurati fino a Lakeshire, nelle Redridge Mountains, e parla con Lucius.", "Mandarti sul campo ora sarebbe un suicidio. Renzik non ha bisogno di un altro ladro morto sulla coscienza. Ma non preoccuparti, {name}: Renzik ti metterà al passo.\n\nRaggiungi le Redridge Mountains e parla con un collaboratore dello SI:7 di nome Lucius. Lo troverai a gironzolare per i moli di Lakeshire con gli altri loschi buoni a nulla.", nil, "Ah, quindi hai le dita un po' grosse, eh? Non preoccuparti, {name}, ho trasformato ladruncoli più inutili di te in ladri esperti.", 0x1179ca1d, 0x8ce09cc7, 0xde207c62, nil, 0xf1b6dc03, "...m." },
  [2282] = { "L'Alther's Mill", "Apri la Lucius's Lockbox, recupera il Token of Thievery e riportalo a Lucius, a Lakeshire.", "Sono anni che addestriamo ladri qui! Del resto, non tutti i furfanti nascono con la grazia e la finezza del vecchio Lucius.\n\nSu, appena fuori dalla strada, troverai l'Alther's Mill. Lassù ho un forziere con dentro una cosa importante. Vai a prendermela! Riporta quel gettone e riceverai il tuo Certificate of Thievery!", "Ho dimenticato di dirti degli orchi?\n\nHo sentito che stanno ficcando il naso dalle parti del mulino.", "L'hai scassinata, eh? Bel lavoro, {name}.\n\nSe muori adesso, possiamo stare tranquilli: sarà stato per la tua stupidità e non per inesperienza.", 0xe7ba8f99, 0x26100448, 0xb5640ee8, 0xe82c551e, 0x0465ee25, "....." },
  [2298] = { nil, "Vai a Stormwind e cerca Renzik \"The Shiv.\"", nil, nil, nil, nil, 0xbbb8bc4a, nil, nil, nil, "m.mmm" },
  [2299] = { "Da Hulfdan!", "Recati a Ironforge e parla con Hulfdan Blackbeard.", "Dove sei <stato/stata>, {name}? Hulfdan ti cerca dappertutto. Pensavamo che il re ti avesse messo ai ferri.\n\nVa' a Ironforge il prima possibile e parla con Hulfdan!", nil, "Abbassa la voce, {name}, le guardie potrebbero sentirti.", 0x612d5545, 0x995810c1, 0x7e2c7b3a, nil, 0x03d4865c, "...m." },
  [2300] = { nil, "Vai a Stormwind e cerca Renzik \"The Shiv.\"", "Renzik ti stava cercando, pivello.\n\nSe fossi in te non farei aspettare il secondo in comando di Mathias.", nil, "Sei <pronto/pronta> a metterti al lavoro o ti serve un pisolino prima di cominciare?", nil, 0xbbb8bc4a, 0xf9063657, nil, 0x6f885d66, "m..m." },
  [2318] = { "Tradurre il diario", "Trova qualcuno in grado di tradurre il diario del paladino. Il luogo più vicino dove potrebbe esserci qualcuno è Kargath, nelle Badlands.", "Trovandoti in una specie di vicolo cieco, sai che ti servirà tradurre il libro in una lingua che puoi capire. Ci sono di certo molte persone al mondo in grado di farlo; il luogo più vicino dove potrebbe esserci qualcuno capace, però, è l'avamposto di Kargath, nelle Badlands. Forse è un buon punto di partenza.", nil, "Possente {class}, so cosa fai qui nelle Badlands. So che cerchi il mio dono delle lingue. Stai cercando le parti di quella collana che hai trovato a Uldaman.\n\n<Sorpreso/Sorpresa>? Non esserlo: è il mio lavoro sapere queste cose. Parliamo piuttosto di cosa farai in cambio di un diario tradotto. Fidati: sono l'unico che troverai in grado di tradurlo.\n\nAnzi, lascia che ti faccia un'offerta migliore di quella di Dran Droffers, che ti permetterà comunque di concludere il tuo accordo con loro. Ora ti interessa, vero?", 0x0fba366a, 0x3f90420d, 0x7bf166bf, nil, 0xd391c145, "...m." },
  [2338] = { "Tradurre il diario", nil, nil, nil, nil, 0x0fba366a, nil, nil, nil, nil, ".mmmm" },
  [2342] = { "Tesori recuperati", nil, nil, nil, nil, 0x029286ee, nil, nil, nil, nil, ".mmmm" },
  [2358] = { nil, "Riporta gli Horns of Nez'ra all'Arantir's Shadow, a Lakeshire.", "Molti anni fa, gli Horns of Nez'ra furono rubati dal maniero di Ravenholdt. Li ho cercati attraverso continenti e oceani, solo per scoprire che queste bestie insignificanti li hanno sempre avuti con sé.\n\nUccidi ogni orco Blackrock che incontri finché non avrai recuperato gli Horns of Nez'ra. Se li recuperi, cercami a Lakeshire.\n\nFallo per me e il tuo nome sarà noto a Ravenholdt, {name}.", "Hai le corna del principe dei demoni?", "Negare a Ravenholdt il manufatto sarebbe come negare la propria esistenza. Ben fatto, <ladro/ladra>. Un giorno potresti camminare tra gli assassini di Ravenholdt.\n\nDa giovane ladro, durante un'avventura a Darkshore, scoprii un tè che ridà energia in combattimento. Mi è stato utile per tutti questi anni, e ora ti faccio assaggiare il thistle tea. Bevine quando sei <stanco/stanca>, {name}, e torna a combattere con vigore!", nil, 0x3b5ab7d3, 0x4584825e, 0xe35c152d, 0x1f0b2efd, "m...." },
  [2359] = { "La torre di Klaven", "Ruba la Defias Tower Key, entra di forza nella Defias Tower e scopri cosa contiene il Duskwood Chest. Porta le informazioni che trovi a Mathias Shaw, a Stormwind. Leggi il Kearnen's Journal per saperne di più sulla torre.", "Sono settimane che sorveglio questa torre, {name}. Di recente è arrivato un grosso carico da Duskwood, e con lui sono arrivate quelle guardie.\n\nCosa sono? Ne so quanto te. Posso dirti una cosa: non sono umani.\n\nComunque, nel carico c'era un forziere, ed è quello che immagino stiano sorvegliando quegli abomini. Lo zombi con gli aculei ha una chiave che ci serve.\n\nPrendi quella chiave, entra nella torre e scopri cosa c'è in quel forziere. Porta quello che trovi a Mathias.", "Notizie da Agent Kearnen?", "Questo spiegherebbe i Defias ridotti a servi senz'anima che tu e Kearnen avete visto fuori dalla torre, {name}. Spiegherebbe anche il coinvolgimento della Venture Company con i Defias e gli strani carichi in arrivo da Duskwood.\n\nSecondo questo libro, i troll Zanzil di Stranglethorn hanno scoperto un modo per resuscitare i morti con le pozioni... o, per essere più precisi: con il veleno.\n\nNon servirai a nulla allo SI:7 senza una solida conoscenza dei veleni, {name}, soprattutto ora che abbiamo a portata di mano la ricetta per creare la non morte.", 0x7a0fe55b, 0x84c572ed, 0xffbbc189, 0x6bdfdca0, 0xea54e6be, "....." },
  [2360] = { "Mathias e i Defias", "Recati a Westfall e trova l'Agent Kearnen per il tuo rapporto.", "Appena in tempo, {name}. La ricognizione dello SI:7 segnala un'attività insolitamente intensa dei Defias a Westfall.\n\nSembra che i Defias abbiano occupato una torre di guardia abbandonata dell'Alliance a sud-est di Sentinel Hill e la usino come base operativa per contrabbandare merci dalla via di rifornimento di Redridge.\n\nVa' a Westfall e contatta l'Agent Kearnen per il tuo rapporto. La troverai nascosta vicino alla torre.\n\n...e {name}, se dovessi essere <scoperto/scoperta>, lo SI:7 negherà di sapere della tua esistenza.", nil, "Mathias ha finalmente mandato un altro agente a darmi man forte, eh? Beh, spero che sia pronto a sentire brutte notizie.", 0x105ec7f9, 0x8fda0905, 0x763fbd75, nil, 0x167ae4df, "...m." },
  [2361] = { "Restaurare la collana", nil, nil, nil, "Ti do volentieri questa collana, {class}. Mi hai reso un servizio inestimabile, e per questo ti ringrazio. Indossala con orgoglio, e assicurati di dire ad alta voce e spesso chi l'ha creata per te!\n\nE se potessi aggiungere che non è davvero maledetta, sarebbe fantastico.", 0xd9740d79, nil, nil, nil, 0x00ee2344, ".mmm." },
  [2398] = { "I nani dispersi", "Trova Baelog a Uldaman.", "Il sito di scavo di Uldaman non è sempre stato invaso. Noi nani di Ironforge controllavamo la zona, ma... era prima che arrivassero i trogg. Sono arrivati così in fretta e così numerosi che nemmeno la forza nanica ha potuto fermarli!\n\nAnzi, il loro attacco è stato così improvviso che temo che parte della nostra gente sia rimasta intrappolata dietro le linee nemiche.\n\nIl mio amico Baelog ha guidato un piccolo gruppo di nani nel profondo del sito poco prima che arrivassero i trogg. Se lui e la sua compagnia sono vivi, voglio che tu li trovi.", nil, "Era ora che ti facessi vivo! Rischiavo di perdere una scommessa con Olaf!\n\nAveva scommesso che la sua barba sarebbe arrivata alle ginocchia prima di vedere un altro {race} vivo. Be', eccoti qui, e come vedi alla barba di Olaf mancano ancora parecchi centimetri.\n\nGrazie, {name}. Dividerò la vincita con te.", 0x826b7a46, 0x194d79a7, 0x1cc327cb, nil, 0xc693cc2f, "...m." },
  [2418] = { "Pietre energetiche", "Porta $N1 Dentrium Power Stones e $N2 An'Alleum Power Stones a Rigglefuzz, nelle Badlands.", "Tempo fa ho avuto un incidente con i nani Shadowforge. Mi hanno portato alla Angor Fortress per studiare due tipi di strane pietre di Uldaman. Ho scoperto che, trattate nel modo giusto, erano fonti di energia durature e stabili. È incredibile cosa si può trovare in quel vecchio sito di scavo!\n\nComunque, dopo che ho rivelato loro il segreto delle pietre, mi hanno cacciato dalla Angor Fortress e hanno cominciato a scavare a Uldaman per trovarne altre.\n\nVoglio quelle pietre per me! Portami entrambi i tipi e ti pagherò profumatamente!", "Hai le pietre energetiche, {name}? Ho un roditore robotico che ha bisogno di una fonte di energia...", "Fantastico, ne hai trovate! Grazie mille, {name}. Sei il {race} più affidabile che abbia mai incontrato!\n\nNon vedo l'ora di provarle su alcuni congegni su cui sto armeggiando. Scommetto che, nelle giuste condizioni, i congegni alimentati da queste pietre andranno avanti, e avanti, e avanti...", 0x2a8fd07d, 0xd762a904, 0x69dbb206, 0x8950568a, 0xa4af47c3, "....." },
  [2438] = { "L'Emerald Dreamcatcher", "Porta l'Emerald Dreamcatcher a Tallonkai Swiftroot, a Dolanaar.", "Una volta Gaerolas Talvethen, il guardiano dei druidi del Ban'ethil Barrow Den, mi regalò un Emerald Dreamcatcher. Questo potente amuleto riesce ad attingere energia dall'Emerald Dream e porta fortuna a chi lo porta con sé.\n\nPurtroppo non sono riuscito a recuperarlo dal mio cassettone a Starbreeze Village... Starbreeze un tempo era un posto tranquillo, ma ora ha ceduto alla corruzione dei furbolg che vi abitano.\n\nSaresti <disposto/disposta> a recuperare il mio acchiappasogni, {class}?", "Ti prego, muoviti in fretta. Posso solo sperare che i furbolg non abbiano danneggiato il mio Emerald Dreamcatcher.\n\nL'hai già recuperato, {name}?", "Il mio Emerald Dreamcatcher è molto importante per me. È un dono concesso a pochi. Grazie per avermelo riportato, {name}.", 0x15f1c399, 0x52a2d29e, 0xfe33a929, 0x164e94f7, 0x1efbac0d, "....." },
  [2439] = { "I dischi di platino", "Porta il tuo buono ricompensa a Dinita Stonemantle, nella Vault di Ironforge.", "Questo oggetto è una scoperta incredibile. Gli antichi titani, o i creatori, come li chiamano questi dischi, sono il legame con la nostra creazione incantata, se il sapere qui custodito è corretto! Dovremo dedicarci quanto più tempo di ricerca possibile.\n\nQuanto a te, eroico {class}, porta questo buono a Dinita Stonemantle, alla Vault. Ti darà ciò che ritengo adeguato per una scoperta così straordinaria!\n\nTorna direttamente da me quando sei <pronto/pronta>: c'è ancora molto da fare per l'Explorers' League!", "<Benvenuto/Benvenuta> nella Vault di Ironforge, {name}. Cosa posso fare per te oggi?", "Ah sì, un buono dell'Explorers' League... e piuttosto prezioso, aggiungerei.\n\nL'Explorers' League mi concede l'autorità di offrirti una scelta di compenso direttamente dalla sua cripta. Riceverai questo oggetto, e come ricompensa puoi scegliere tra cinque pozioni di cura superiori o cinque pozioni di mana superiori.", 0xd5650943, 0x5d43047f, 0x819d9adb, 0xa99640aa, 0x38a04709, "....." },
  [2440] = { "I dischi di platino", nil, nil, nil, nil, 0xd5650943, nil, nil, nil, nil, ".mmmm" },
  [2459] = { nil, "Tallonkai Swiftroot, a Dolanaar, vuole che tu uccida 7 Gnarlpine Mystics e trovi il Missing Jewel.", "Lo smeraldo... Manca! Il mio acchiappasogni è stato danneggiato!\n\nA nord di Starbreeze c'è una banda di mistici Gnarlpine. Ho sentito dire che il loro capo, Ferocitas the Dream Eater, porta una collana che brilla di verde nella notte. Ora che vedo il mio acchiappasogni, sono certo che mi ha rubato lo smeraldo... Non capirebbe mai che il suo potere per lui è inutile.\n\nTrova il gioiello mancante, {name}. E, già che ci sei, fai piazza pulita di qualcuno di quei mistici corrotti.", "Ferocitas e i mistici Gnarlpine devono restituire ciò che è mio. Ti prego, recupera lo smeraldo, così potrò riparare il mio Emerald Dreamcatcher.", "Ora posso riparare il mio acchiappasogni. Grazie, {name}.", nil, 0x4c50de14, 0x837c9efe, 0x9c2bf253, 0x00d792cf, "m...." },
  [2478] = { "Missione: possibile ma non probabile", "Ruba la Silixiz's Tower Key al Foreman Silixiz, poi uccidi due Mutated Venture Co. Drone, due Venture Co. Patroller e due Venture Co. Lookout.\n\nAssassina il Grand Foreman Gallywix e prendi la sua testa, poi scassina la cassetta di Gallywix e ruba la Cache of Zanzil's Altered Mixture. Riporta la Cache e la Gallywix's Head a Shenthul, a Orgrimmar, per ulteriori istruzioni.", "Dovrai rubare la chiave della torre al Foreman Silixiz, {name}. Una volta in tuo possesso, tienila: potrebbe servirmi più tardi.\n\nRicorda, il veleno ha indebolito tutto in questa torre. Usa le tue capacità per portare caos e distruzione tra i suoi abitanti. Uccidili tutti, senza pietà!\n\nQuando tutto all'interno giacerà in un mucchio insanguinato, scassina la cassetta di Gallywix e ruba la scorta della miscela di Zanzil che contiene. Porta sia la testa di Gallywix sia la miscela a Shenthul, a Orgrimmar.", "Che cosa hai da riferire, {name}?", "Povero Fizzule, era un buon agente, uno dei nostri migliori. Ahimè, è il prezzo da pagare, {name}. Essere un agente sul campo della Shattered Hand è un lavoro pericoloso.\n\nHai svolto bene il tuo dovere, {class}. Sarebbe un peccato se non vivessi abbastanza per servirci di nuovo.", 0x889d9a10, 0x323252b6, 0xc695e02b, 0xd8f33c29, 0x2c36763c, "....." },
  [2498] = { "Ritorno da Denalan", "Rellian Greenspyre vuole che tu parli con Denalan, al Lake Al'Ameth.", "Mi è appena giunta notizia che Denalan, al Lake Al'Ameth, ha scoperto quella che potrebbe essere la causa dei tumori che affliggono i timberling. Ti prego, parla con lui e digli che ti mando io.\n\nSbrigati, {name}: ha bisogno del nostro aiuto.", nil, "Ah, quindi ti manda Rellian ad aiutarmi. Sono contento che tu sia <arrivato/arrivata> così presto.\n\nHo scoperto qualcosa di molto inquietante!", 0x86434b8b, 0x01cfe979, 0x16e96e4d, nil, 0xbdb97620, "...m." },
  [2499] = { nil, "Denalan, al Lake Al'Ameth, vuole che tu prenda il Gargantuan Tumor da Oakenscowl.", "In una caverna sulla sponda meridionale del lago, un timberling di nome Oakenscowl sta diffondendo la corruzione a tutte le creature che vivono al Lake Al'Ameth.\n\nNon ho osato avvicinarmi troppo, ma anche da lontano è evidente: Oakenscowl è avvelenato dal tumore più grande che abbia mai visto... direi persino gargantuesco.\n\n{name}, hai già fatto molto per aiutarmi, ma ti chiedo un altro compito. Dai la caccia a Oakenscowl e prendi il tumore; togli questa fonte di corruzione da casa mia.", "Hai già trovato Oakenscowl, {race}?", "Sapevo che eri più che in grado di liberare il lago da quell'orribile bestia.\n\nÈ una situazione angosciante; un tempo Oakenscowl era un grande capo tra i suoi simili... ma la corruzione non fa distinzione tra umili e nobili.\n\nLe dimensioni di questo tumore sono molto inquietanti, ma devo studiarlo per saperne di più sulla malattia che sconvolge i timberling.\n\nGrazie, {name}.", nil, 0x0d86e120, 0x1f483fdc, 0x5c25b955, 0x92662c82, "m...." },
  [2500] = { "Reagenti dalle Badlands", "Procura nelle Badlands i reagenti che servono a Ghak Healtouch, poi torna da lui a Thelsamar.", "{class}, vorrei servirmi dei tuoi servigi. Sono un alchimista di una certa fama, e cerco il tuo aiuto per procurarmi alcuni reagenti che si trovano nelle Badlands.\n\nMi servono queste cose per rifornire le scorte: 5 Buzzard Gizzards, 10 Crag Coyote Fangs e 5 Rock Elemental Shards. Ovviamente puoi prenderli dalle bestie stesse; se non sei il tipo da combattere, trova degli amici che lo siano.\n\nProcurami queste cose e ci guadagnerai qualche moneta.\n\nAllora, che ne dici?", "Hai già le cose che mi servono? Non sarai <pagato/pagata> finché non mi porti quei reagenti.", "Ah, ben fatto {name}. Questi dovrebbero bastarmi almeno per un po'. Ecco la tua paga, come promesso.\n\nSe ti interessa, ho altri reagenti che mi farebbero comodo. Questi però si trovano solo nelle profondità dello scavo di Uldaman. Non sarà facile procurarli, ma se vorrai aiutarmi ancora ne varrà la pena.\n\nMagari qualcosa di più di qualche moneta luccicante, eh?", 0xaca0069d, 0xf4c53465, 0xe9758759, 0x5be9782d, 0xf953efd3, "....." },
  [2501] = { "Reagenti dalle Badlands II", "Usa i recipienti taumaturgici vuoti sui draghi guardiani bruciati delle Badlands. Quando saranno pieni, portali a Ghak Healtouch, a Thelsamar.", "Mi sei <stato/stata> di grande aiuto, {name}. Vorrei ricompensarti con la ricetta stessa dell'intruglio che ti ho dato prima, ma devo chiederti un favore piuttosto pericoloso.\n\nQuesta cassetta contiene tre recipienti taumaturgici vuoti; sono impregnati di un'aura di sintonia che assorbirà il sangue di uno scorched guardian dragon. Usarne uno sulla bestia la farà infuriare parecchio, quindi stai <attento/attenta>. Quando li avrai riempiti tutti e tre, portameli.\n\nFallo, e la ricetta sarà tua.", "Hai usato i recipienti per procurarmi il sangue di scorched guardian dragon che mi serve? Sì, lo so che è un compito pericoloso... ma la ricetta del mio intruglio ricostituente aspetta il tuo successo. Rischio e ricompensa, amico mio... rischio e ricompensa...", "Da alchimista ad alchimista, ti rendo onore. Tieni, prendi questa ricetta e imparala bene. Che ti porti il successo e le ricompense che ha portato a me in tutti questi anni!", 0x883768bc, 0xb97f5a02, 0x928aded5, 0x0cf00f74, 0xb7d7a9aa, "....." },
  [2518] = { "Lacrime della luna", "Priestess A'moora, nel Temple of the Moon di Darnassus, vuole che tu le porti le Lady Sathrah's Silvery Spinnerets.", "Un tempo Lady Sathrah era amata da Elune. Aggraziata e pura, la ragnessa tesseva i suoi fili d'argento al chiaro di luna, catturando la nebbia della sera. La rugiada argentea aveva forti poteri curativi e veniva custodita qui nel tempio.\n\nMa ultimamente Sathrah è sprofondata nella follia. Ora sono minacciate anche le sue generazioni future.\n\nTrova Lady Sathrah, {name}, e metti fine alla sua sofferenza. Vive lungo i confini settentrionali di Teldrassil, vicino al Wellspring Lake. Raccogli le sue filiere argentee e riportamele.", "Mi dispiace per il compito che ti ho chiesto di svolgere; ma per Lady Sathrah non c'è più speranza.\n\nSperiamo di offrire a Elune il sacrificio delle filiere. Con questo sacrificio, Elune benedirà Sathrah perché possa rinascere, e trovare la pace.", "La foresta piange Lady Sathrah, ma era una cosa che andava fatta.\n\nGrazie, {name}.", 0x590caf7f, 0x6c622142, 0x20922da4, 0x35d5c5a2, 0x309445ea, "....." },
  [2519] = { "Il Temple of the Moon", "Sister Aquinne vuole che tu parli con Priestess A'moora, nel Temple of the Moon.", "Una creatura della foresta, un tempo grande, ha bisogno di aiuto, {race}.\n\nC'è un compito difficile da svolgere.\n\nTi prego, cerca Priestess A'moora: ti spiegherà lei. La trovi a sud-est di qui, dentro il Temple of the Moon.", nil, "Dunque ti manda Sister Aquinne?", 0xbf995b33, 0xfccb6f52, 0xb532fd45, nil, 0x4f3a53a8, "...m." },
  [2520] = { nil, "Priestess A'moora vuole che tu metta le filiere argentee di Lady Sathrah alla fontana dentro il tempio, poi torni da lei.", "Ora devi completare il compito che ti è stato affidato. Prendi le filiere e offri il sacrificio di Lady Sathrah a Elune; dai riposo alla grande ragnessa.\n\nDentro questo tempio, trova la fontana centrale. È lì che puoi lasciare il sacrificio. Le acque sacre purificheranno e laveranno la corruzione che ha fatto impazzire Sathrah.\n\nQuando avrai finito, torna da me.", "Hai posato il sacrificio alla fontana, {name}?", "La perdita di Lady Sathrah è dolorosa, ma solo così potrà rinascere con uno spirito nuovo.\n\nChe Elune accetti di buon grado il sacrificio che le hai offerto.", nil, 0x6736b09f, 0x7b40ee6c, 0xf5b1c4b7, 0xbd5ac00f, "m...." },
  [2521] = { "Al servizio di Kum'isha", "Durante i tuoi viaggi per le Blasted Lands, se mai trovassi una Flawless Draenethyst Sphere, portala a Kum'isha the Collector.\n\nAttenzione: questa gemma è uno dei cristalli più rari di tutta Azeroth. Qualsiasi creatura di queste terre potrebbe avere una Flawless Draenethyst Sphere.\n\nSarai <ricompensato/ricompensata> per ogni Flawless Draenethyst Sphere che avrai raccolto.", "{race}, il tuo minuscolo cervello riesce a comprendere la rarità di una sfera di draenethyst perfetta? I draenei hanno passato vite intere a cercare uno solo di questi cristalli, per poi andare incontro a destini orribili senza aver compiuto il loro scopo.\n\nE così ti presenti davanti a Kum'isha, sapendo cosa Kum'isha ha chiesto, e vuoi ancora aiutare? Molto bene, {race}... In qualsiasi momento dei tuoi viaggi per queste terre, se trovassi una sfera di draenethyst perfetta, riportamela e ti ricompenserò con ricchezze oltre i tuoi sogni più sfrenati.", "Ho dedicato la mia vita alla ricerca di sfere di draenethyst perfette. Una vita intera, {race}!", "I miei occhi m'ingannano? Impossibile! Dove hai... Come...\n\nForse ora si potrà aprire un varco per riportarci nella nostra terra natale.", 0x81cce1f7, 0x009332b5, 0xa4c5c9f1, 0x71ae7976, 0xf92902be, "....." },
  [2541] = { "Il druido dormiente", "Porta uno Shaman Voodoo Charm a Oben Rageclaw, nel Ban'ethil Barrow Den.", "Gli sciamani Gnarlpine che abitano questo posto hanno scoperto un modo per separare lo spirito di un druido addormentato dal suo corpo fisico. I furbolg hanno animato la mia forma fisica e la usano per attaccare chiunque tenti di esplorare il Ban'ethil Barrow Den. Ora sono intrappolato nell'Emerald Dream, senza poterlo impedire.\n\nDevi aiutarmi. Gli sciamani Gnarlpine portano uno strano amuleto con cui eseguono questo rituale, e vorrei esaminarlo. Ti prego, {name}, portamene uno.", "Se potessi esaminare l'amuleto, forse capirei come spezzare l'incantesimo. Ne hai trovato uno?", "Grazie, {name}.\n\nChe strano ninnolo è questo... sento l'aura immonda che ne emana; è un incantesimo molto potente.", 0xf13c0bd8, 0xb6182866, 0xcd3565db, 0x8fcb5c05, 0x37128c11, "....." },
  [2561] = { "Druido dell'artiglio", "Oben Rageclaw vuole che tu uccida il suo corpo senz'anima, poi usi il Voodoo Charm.", "Dopo aver esaminato questo amuleto, {name}, ora capisco cosa va fatto. Ti prego, prendilo e fai come ti chiedo.\n\nDevi esplorare le zone più profonde del Ban'ethil Barrow Den. Lì troverai il mio corpo senz'anima... Anche se mi dispiace dirtelo, non vedo altro modo per liberarmi dal controllo dei Gnarlpine.\n\nPer sfuggire loro, devi uccidere la mia forma fisica. Fatto questo, usa il Voodoo Charm sul mio corpo caduto. Quando avrai finito, ti prego, torna da me.", "{name}, stai <attento/attenta> quando ti avvicini alla mia forma fisica; l'incantesimo che la domina è molto potente.", "Finalmente sono libero dal controllo dei Gnarlpine. Grazie, {name}.\n\nOra il mio spirito potrà riposare in pace per sempre nell'Emerald Dream.\n\nForse un giorno ci rincontreremo, giovane {class}. Ma per ora, ti prego, accetta questa ricompensa come segno della mia gratitudine.", 0xdcee0406, 0x31a8c3fe, 0x9102b8db, 0x56e2ee75, 0x992edece, "....." },
  [2581] = { nil, "Porta tre Snickerfang Jowls, due Blasted Boar Lungs e uno Scorpok Pincer al Bloodmage Drazial.", "È risaputo che le iene hanno una forza tremenda nelle mascelle, ma la forza di spezzare tre pollici di acciaio di thorium? Impossibile, improbabile, eppure l'ho visto dimostrare con i miei occhi.\n\nAvventurati nelle Blasted Lands e portami tre mascelle di snickerfang. Mentre cerchi gli snickerfang, tieni d'occhio cinghiali e scorpok: il primo saggio richiede anche due polmoni di cinghiale delle terre devastate e una chela di scorpok.", "Puzzi, {name}. Sei <andato/andata> a zonzo nei campi di zolfo? E dove sono i miei componenti?!", "Come ti senti, {name}? Irradi l'aura dello snickerfang: la tua forza, senza pari tra i mortali!\n\nPurtroppo, con i componenti che mi hai portato, sono riuscito a preparare abbastanza saggio per una sola tavoletta. Mi serviranno altri componenti, se vorrai un'altra tavoletta.", nil, 0xb51443a6, 0x3ee63bcd, 0xd475d33e, 0x0973a15f, "m...." },
  [2583] = { "La vitalità del cinghiale", "Porta tre Blasted Boar Lungs, due Scorpok Pincers e un Basilisk Brain al Bloodmage Drazial.", "In queste terre devastate esistono due specie di cinghiale: il cinghiale criniera di cenere e l'helboar.\n\nSembra che la resistenza di queste bestie le renda quasi invulnerabili, tanto che gli altri animali le trovano troppo difficili da uccidere e, di conseguenza, non ne vale la pena.\n\nDobbiamo fare altre analisi, {name}. Se mi porti tre polmoni di cinghiale delle terre devastate, due chele di scorpok e un cervello di basilisco, creerò un elisir divino dal residuo del saggio. Sarai la mia prima cavia!", "Dove sono gli organi, {name}!?", "Lo spirito del cinghiale illumina il tuo essere, {name}! Mi chiedo: ti credi invulnerabile come queste bestie?", 0x9a4e1685, 0x97393e8f, 0x2a64bd84, 0x307f3aa2, 0x73abbfa6, "....." },
  [2585] = { "Il colpo decisivo", "Porta tre Scorpok Pincers, due Vulture Gizzards e un Blasted Boar Lung al Bloodmage Drazial.", "Li hai mai visti combattere, {name}? Gli scorpok, intendo. Hai mai visto la grazia e l'agilità con cui si muovono? La decisione dei loro colpi?\n\nSe solo potessimo isolare quell'agilità e racchiuderla, saremmo ricchi oltre ogni... cioè... sarebbe una manna per la comunità scientifica.\n\nAiutami, {name}, e ti concederò un assaggio del saggio.\n\nPer creare un campione stabile mi serviranno tre chele di scorpok, due ventrigli di avvoltoio e un polmone di cinghiale delle terre devastate.", "Dove sono gli organi, {name}!?", "Affascinante. Questo è stato il saggio più difficile di tutti da analizzare.\n\nPrendi un pizzico di questo sale residuo e mettilo sotto la lingua. Dovresti provare una leggera euforia, seguita da uno stato di agilità e rapidità senza precedenti.", 0x0a859cb2, 0xab76c31d, 0xc7ff6f5a, 0x307f3aa2, 0xf5293056, "....." },
  [2601] = { "Il morso del basilisco", "Porta dieci Basilisk Brains e due Vulture Gizzards al Bloodmage Lynnore.", "Queste terre desolate pullulano di basilischi di pietrarossa, {name}. Questi basilischi si sono adattati e hanno prosperato più di qualsiasi altra fauna della regione.\n\nLi ho osservati da lontano mentre cacciano e svolgono le loro attività quotidiane: le bestie mostrano un processo di pensiero più complesso persino di alcuni umanoidi.\n\nDevo studiare i loro cervelli!\n\nRecuperamene dieci, {name}. Il composto però non può essere completo senza due ventrigli di avvoltoio a fare da base della soluzione.", "Sei <tornato/tornata> con gli organi richiesti?", "È meraviglioso, {name}! Ti offro un assaggio del funzionamento interno del basilisco di pietrarossa.\n\nSe il composto è di tuo gradimento, se ne può sempre preparare dell'altro... a pagamento.", 0x20ee9432, 0xa6edac7a, 0xafb93fc0, 0x7cfd6e6c, 0x0b5fda6b, "....." },
  [2603] = { "Il vigore dell'avvoltoio", "Porta dieci Vulture Gizzards e due Snickerfang Jowls al Bloodmage Lynnore.", "In queste terre devastate la morte ha davvero le ali, {race}. Ho visto i black slayer e i bonepicker banchettare sul cadavere di molti esploratori caduti, a volte nutrendosi delle carcasse più ripugnanti e malate. È un mistero, quindi, come il loro organismo superi la pestilenza che affligge queste terre.\n\nAiutami nei miei studi, {name}! Mi servono ventrigli! Per la base dell'intruglio serviranno anche due mascelle di snickerfang.\n\nSarai <ricompensato/ricompensata> due volte per i tuoi sforzi.", "Non farmi perdere tempo, {name}. Non abbiamo niente di cui parlare, a meno che tu non abbia recuperato gli oggetti che ti ho chiesto.", "Eccellente! Mi metto subito al lavoro. Forse troveremo una cura per molti dei mali del mondo!\n\nAh sì, la tua ricompensa. Naturalmente, se ti servisse altra di questa gomma, torna da me e ti verrà affidato un altro compito.", 0xf578d486, 0x341217f6, 0x95cfa89c, 0xb053bb62, 0x33e80ed6, "....." },
  [2607] = { "Il tocco di Zanzil", "Parla con il Doc Mixilpixil nella cantina delle Barracks.", "Sembra che tu abbia riportato più informazioni di quante me ne aspettassi persino io. È davvero una strana piega degli eventi, {name}.\n\nUna cura? Mmm... Scendi in cantina e parla con il Doc Mixilpixil: potrebbe aiutarti.", nil, "Era ora! Metti il formaggio sul tavolo e sparisci. Osborne ti pagherà all'uscita.", 0x11470d66, 0xad163fb8, 0x32b769f3, nil, 0x006a9227, "...m." },
  [2608] = { "Il tocco di Zanzil", "/Lay: sdraiati per farti esaminare dal Doc Mixilpixil. Come può trovare la cura se non trova la causa?", "Oh, cielo, sembri la morte. Correggo: ho visto la morte, e tu sembri peggio della morte. Tu, <signore/signorina>, saresti ciò che la morte ha tossito durante la sua ultima visita medica.\n\nAh! Hai sentito, Noarm? Prendine nota!\n\n*coff* mmm, sì, per aiutarti dovrò prelevarti un po' di sangue. Non preoccuparti, fa male solo le prime... cinquanta volte o giù di lì... Usa /lay quando sei <pronto/pronta> per il trattamento, {name}.", "Quando sei <pronto/pronta> per l'esame, sdraiati a terra (/lay) e comincerò il salasso.", "Dammi un momento per consultarmi con i miei colleghi, {name}. Dr. Montgomery, signor Noarm, a consulto!", 0x11470d66, 0xc7da4c18, 0x83e14b94, 0x27c52fde, 0x5baee4be, ".....", nil, nil, 0x0305c147, nil, nil },
  [2609] = { "Il tocco di Zanzil", "Porta al Doc Mixilpixil un mazzo di Simple Wildflowers, una Leaded Vial, un Bronze Tube e uno Spool of Light Chartreuse Silk Thread. La 'ite' non guarisce da sola, <giovanotto/signorina>.", "È unanime, {name}. Hai la 'ite'.\n\nPer fortuna ho una cura per la 'ite'.\n\nEcco cosa mi serve: un mazzo di simple wildflower, una leaded vial, un bronze tube e, ultimo ma non meno importante, uno spool of light chartreuse silk thread. La vecchia Emma me ne ha lasciato un rocchetto a 'The Finest Thread'. Trovi il negozio lungo i canali.\n\nOra sbrigati, {name}, e cerca di non toccare nessuno finché non sarai <guarito/guarita>. Ah, e il Dr. Montgomery dice che ti serve una doccia: parole sue, non mie.", "Se vuoi guarire dalla 'ite', dovrai impegnarti di più, {name}. Dove sono i reagenti per la cura?", "Cosa sto facendo? Cosa ti sembra che stia facendo? Sto preparando una cura per la tua 'ite'! Non indignarti con me adesso, {name}!\n\nAncora qualche secondo. Ecco! Spruzzati addosso questa, ehm, medicina dal profumo fantastico e tornerai <nuovo/nuova> di zecca.", 0x11470d66, 0xd6faf98a, 0xdeee9d37, 0x82beeccc, 0xfb99b7cf, ".....", nil, 0x6c5f6143, nil, nil, nil },
  [2681] = { "Le pietre che ci legano", "Libera nove Servants of Razelikh, tre Servants of Sevine, tre Servants of Allistarj e tre Servants of Grol. Torna dal Fallen Hero quando avrai completato il compito. Devi restare vicino alle pietre, o il procedimento fallirà.", "Da solo non basterai a sconfiggere le forze di Razelikh e dei suoi sottoposti.\n\nRaduna un gruppo di avventurieri adatto e libera i miei uomini dalla loro tortura eterna! Diciotto pietre dovrai frantumare.\n\nCombatti con forza e muori con onore, {name}.", "Non è un compito facile, {name}. Non arrenderti!", "Ce l'hai fatta, {name}! Le povere anime torturate possono finalmente riposare.\n\nIl nostro lavoro non è ancora finito, {name}. Abbiamo molto di cui parlare e molto altro da compiere.", 0xb9c0ca74, 0x954b0e18, 0xe5fcf65b, 0x2db7e4f8, 0xd8cd7b43, "....." },
  [2701] = { "Eroi d'altri tempi", nil, nil, nil, nil, 0x66b9e903, nil, nil, nil, nil, ".mmmm" },
  [2702] = { "Eroi d'altri tempi", "Parla con il caporale Thund Splithoof.", "Mi hai onorato con la tua nobiltà e il tuo eroismo, {name}.\n\nE hai onorato anche loro...", nil, "Davvero, ci hai onorati tutti. I nostri soli ringraziamenti non bastano.", 0x66b9e903, 0x30807b26, 0xa2f524f9, nil, 0xe07e9f96, "...m." },
  [2721] = { nil, "Scopri che fine ha fatto il tenente Kirith.", "Mentre un capitolo della tua avventura si chiude, un altro si apre, {name}.\n\nUno dei miei uomini manca ancora all'appello, disperso da qualche parte nelle Blasted Lands. Parlo del tenente Kirith, naturalmente.\n\nCome ti dicevo, siamo stati entrambi imprigionati e torturati da Allistarj, ma il povero Kirith ha ceduto nella forza di volontà. Sentivo gli esperimenti dalla mia gabbia; le grida di tortura risuonavano per i corridoi della caverna. È l'ultima volta che ho visto o sentito Kirith.", nil, "Trebor? Ti manda Trebor?", nil, 0xa3197881, 0x5ce3d883, nil, 0x38fc0acd, "m..m." },
  [2743] = { "Il manto dell'oscurità", "Torna dal Fallen Hero of the Horde con ciò che hai scoperto.", "Non giriamoci intorno, {race}: il mio tempo qui è limitato.\n\nDevi distruggere la triade del potere che protegge il signore dei demoni, Razelikh. Non sarà semplice come liberare un'anima dannata.\n\n<Kirith sogghigna.>\n\nVedi, ciascuno dei sottoposti di Razelikh porta al collo un terzo di un amuleto creato da Razelikh. Lo stesso amuleto che ti servirà per evocare l'arcidemone.\n\nTorna da Trebor e digli cosa serve per evocare Razelikh. Potrà darti altre istruzioni.", nil, "Il signore dei demoni mostra un'astuzia calcolata quasi quanto la sua brutalità, {name}.", 0x6aba07e4, 0x3827a7a4, 0xf90b2858, nil, 0x5627f8b3, "...m." },
  [2744] = { "Il cacciatore di demoni", "Parla con Loramus Thalipedes ad Azshara.", "La triade è protetta da Razelikh.\n\nIn cambio della loro servitù, Razelikh ha concesso a ciascuno un potere quasi illimitato nelle Blasted Lands. I pezzi dell'amuleto sono legati alla forza vitale dei loro proprietari e li rendono immortali. Finché restano nelle Blasted Lands non possono essere uccisi, e la loro vita si prolunga fino alla fine dei giorni.\n\nC'è qualcuno che potrebbe aiutarti ancora, {name}. Viaggia fino ad Azshara e trova il cacciatore di demoni Loramus Thalipedes. Cerca sulle isole.", "Che ci fai qui?", "Ti aiuterò. Anche se non credo che tu capisca davvero contro cosa ti stai mettendo.", 0x94f424b7, 0x52d8585c, 0xada03b34, 0xb27a2670, 0xb056674e, "....." },
  [2745] = { "Infiltrarsi nel castello", "Parla con Tyrion, nello Stormwind Castle.", "Mmm, una storia interessante, e da non prendere alla leggera. Sì, posso aiutarti, ma per portare a termine la cosa dovrai amministrare una forma di giustizia che non è... legale.\n\nBisogna occuparsi di Lescovar e Marzon, e in fretta. Pensi di esserne in grado?\n\nDecidi tu. Se sì, corri al castello e trova un mio vecchio amico, uno gnomo di nome Tyrion. Tiene d'occhio Lescovar da un paio di settimane. Dovrebbe poterti aiutare a chiudere la faccenda.", nil, "Ma che...?! Non sbucarmi alle spalle così! E abbassa la voce! In nome dell'Ombra, perché mi arrivi alle spalle di soppiatto? Non vedi che sono occupato, <sciocco/sciocca> che non sei altro?\n\nCome sarebbe, cosa sto facendo? Aspetto che si apra il prossimo Dark Portal, cosa diavolo credi che stia facendo? Di' quel che devi e vattene... prima che le guardie notino noi due nascosti insieme tra i cespugli. Ho una reputazione da mantenere.", 0x8aa81dca, 0xffe1ba3d, 0x31a5101a, nil, 0xd55e7590, "...m." },
  [2746] = { "Oggetti di una certa importanza", "Porta 3 Silk Cloth e 2 Clara's Fresh Apples a Tyrion, a Stormwind.", "Trias vuole anticipare i tempi, eh? Va bene, si può fare, ma non sono pronto. E sappi una cosa: io faccio la parte difficile, ma sarai tu a sporcarti le mani, capito? Bene.\n\nAllora, ho bisogno che tu mi procuri un paio di cose prima di mettere in atto il mio piano. Ho il travestimento perfetto per far passare Spybot davanti a quelle guardie.\n\nPortami un po' di seta e un paio di mele. La seta trovala tu, ma la fattoria di Clara, appena fuori città, ha mele della misura perfetta.", "Tengo d'occhio Lescovar da un paio di settimane. Trias non si è mai fidato di lui, ma non sospettavamo che avesse a che fare con la Defias Brotherhood. Seguivamo piste che lo collegavano al Twilight's Hammer. In ogni caso, è diventato più pericoloso di quanto questa città possa gestire, ed è qui che entriamo in gioco noi.\n\nProcurami quegli oggetti e potremo mettere in atto il mio piano.", "Questi andranno benissimo, {name}. Ottimo lavoro.\n\nIl resto dell'attrezzatura che mi serve è nel mio zaino... grazie alla Luce, una mia amica sarta mi ha appena fatto una borsa di seta. Stavo finendo lo spazio per portarmi dietro tutta la roba.\n\nPrima che Spybot entri, definiamo i dettagli, così saprai cosa devi fare.", 0x1f4eb590, 0x1d0c75b3, 0x1b56c1ff, 0xb3384936, 0x8b76d0c1, ".....", nil, nil, 0xde7d35a2, nil, nil },
  [2757] = { nil, "Parla con McGavan, a Booty Bay.", nil, "Quelli come te sono una razza rara, compare. Fammi vedere quell'insegna.", "Per i peli della schiena di Blackhoof: finalmente qualcuno degno del Mithril Order!", nil, 0x76671185, nil, 0xbd77d15c, 0x83bb6990, "m.m.." },
  [2758] = { "Le origini della forgiatura", "Porta sei Golden Scale Bracers a Hank the Hammer, a Stormwind.", "Quando avevo più o meno la tua età, un nano di nome Galvan mi prese sotto la sua ala e mi addestrò nell'arte del forgiatore d'armature. Prima di partire per Booty Bay, mi fece promettere di addestrare tutti coloro che avessero il desiderio e la determinazione di progredire nell'arte della forgiatura; ed eccomi qui, dopo tutti questi anni.\n\nQuindi ora è il momento che tu impari qualcosa. Fammi sei golden scale bracer e scoprirai da dove viene la forgiatura, {name}.", "Potresti essere la prossima persona protetta di Galvan?", "Molto bene, {name}! Ascolta e impara.\n\nLa forgiatura non viene mai da qui! <Hank indica il suo martello.>\n\nLa forgiatura non viene mai da qui! <Hank indica l'incudine.>\n\nLa forgiatura viene solo da qui! <Hank indica il suo cuore.>\n\nE ora conosci l'origine della forgiatura.", 0x5dd39489, 0x350387d3, 0x870eb53b, 0x1e10ca8a, 0xeb39dca0, "....." },
  [2759] = { "Alla ricerca di Galvan", "Parla con McGavan, a Booty Bay.", "Anche se Galvan ha lasciato Booty Bay molti anni fa, membri dell'ordine sono ancora in città, sperando di trovare un giorno un altro degno degli insegnamenti di Galvan.\n\nPrendi questa insegna e presentala a McGavan, a Booty Bay.\n\nSe arriverai davvero fin lì, saprà che ne sei <degno/degna>. Ho fiducia in te, {name}!", "Quelli come te sono una razza rara, compare. Fammi vedere quell'insegna.", "Per i peli della schiena di Blackhoof: finalmente qualcuno degno del Mithril Order!", 0x4dfe8db2, 0x76671185, 0x9fa6b639, 0xbd77d15c, 0x83bb6990, "....." },
  [2766] = { nil, nil, nil, "Sembra che tu abbia scoperto i rottami di... una gallina robotica? La voce dall'interno dell'uovo gracchia di nuovo:\n\n\"Sì, ottimo lavoro! Questo è proprio il mio robot di ritorno, anche se i miei sensori indicano che ha bisogno di una spinta per avviarsi prima di poter volare a Booty Bay per le riparazioni. Avanti, metti il radiofaro dentro il robot: al resto ci penserà il radiofaro!\"", nil, nil, nil, nil, 0xae44575b, nil, "mmm.m" },
  [2769] = { "I fratelli Brassbolts", "Parla con Wizzle Brassbolts, nelle Shimmering Flats.", "Hai conosciuto i fratelli Brassbolts? Sono nelle Shimmering Flats, a Kalimdor, a gareggiare con la loro auto a razzo contro i goblin. Di solito vincono, e non c'è da stupirsi: l'auto dei goblin esplode così spesso che quasi mai taglia il traguardo!\n\nMa anche così i fratelli Brassbolts cercano sempre nuovi modi per rendere la loro auto più veloce, e Wizzle mi ha detto che gli serve un componente rarissimo per il suo prossimo esperimento.\n\nProbabilmente ha bisogno d'aiuto per procurarselo. Parlagli e scoprilo.", nil, "Ah, vuoi aiutarmi? Fantastico!\n\nC'è un pezzo che mi serve per un esperimento a cui sto lavorando, e ho bisogno di un {class} coraggioso come te per procurarmelo!", 0x089469a7, 0xb1fcc703, 0x1fabb59b, nil, 0x80c2ec73, "...m." },
  [2782] = { nil, "Oran Snakewrithe, studiosa nota per le sue conoscenze sui troll Witherbark, potrebbe riuscire a decifrare la tavoletta. Si dice che risieda nel Magic Quarter di Undercity.", "La tavoletta è coperta di segni dei troll Witherbark. Il segreto di Rin'ji è davvero un mistero...\n\nÈ possibile che tu abbia tra le mani qualcosa di molto prezioso. D'altra parte, è anche possibile il contrario. Un troll Witherbark in difficoltà farebbe probabilmente di tutto per tirarsi fuori dai guai...", "Be', e questo cos'è?", "Questa tavoletta... Piuttosto insolita... Dove l'hai trovata, {name}?", nil, 0xacdc06a9, 0xc21069d7, 0xd520768c, 0x51b1062d, "m...." },
  [2783] = { "Litigi meschini", "Parla con il Fallen Hero of the Horde al confine tra le Blasted Lands e la palude.", "Combattiamo il nemico sbagliato, {name}.\n\nIl vero potere di queste terre continua a crescere in forza e numero mentre noi litighiamo con gli orchi per della terra bruciata.\n\nContinueremo a combattere una guerra contro l'Orda in queste terre, solo per essere sbaragliati un giorno dagli eserciti della Burning Legion? È inutile.\n\nMetti da parte le divergenze, {name}, e parla con l'Eroe caduto dell'Orda. Conosce la verità sulle Blasted Lands.", nil, "L'Alleanza vuole aiutare?\n\nPensavo che non avrei mai più visto questo giorno. Un giorno in cui l'Alleanza combatte fianco a fianco con l'Orda contro un nemico comune.\n\nCosì sia... ci uniremo.", 0xfd0feee3, 0xdc8a1010, 0xa7547fc4, nil, 0x1a69cea0, "...m." },
  [2784] = { nil, "Ascolta il Fallen Hero of the Horde raccontare la sua storia.", nil, nil, nil, nil, 0xcc5274d5, nil, nil, nil, "m.mmm" },
  [2801] = { "Una storia di dolore", "Ascolta il Fallen Hero of the Horde raccontare la sua storia.", "Prima di continuare, devi ascoltare la mia storia.", "Ascolta quello che ho da dire, {name}.", "Il momento di agire è adesso, {name}.", 0x76eea50b, 0xcc5274d5, 0x7cce8f86, 0x8967c526, 0x75013208, "....." },
  [2877] = { "Ripulire Skulk Rock", "Uccidi $N1 Green Sludges e $N2 Jade Oozes, poi fai rapporto a Fraggar Thundermantle, ad Aerie Peak.", "Noi Wildhammer ricordiamo il passato più dei nostri fratelli di Ironforge. Se vuoi farti degli amici qui, sporcati le mani per noi!\n\nL'Orda ha abbandonato le sue posizioni nelle Hinterlands attorno a Skulk Rock; ora è invasa da melme e fanghiglie schifose. Abbiamo dei piani per quella zona, ma prima ci serve una squadra di pulizia che ci apra un varco.\n\nEd è qui che entri in gioco tu, tesoro! Scendi laggiù e fai fuori dieci green sludge e dieci jade ooze, poi torna a fare rapporto da me. In marcia!", "Non provare a contrattare sulla missione, {race}! Se gli dei avessero voluto quelle melme morte, avrebbero già fatto il miracolo, no?!", "Ma guarda, aiuti i Wildhammer! Sei un {class} d'azione, e qui rispettiamo l'azione.\n\nLa tua piccola missione di pulizia è molto più importante di quanto pensi. Con qualcuno che sfoltisce le melme e le fanghiglie, potremo estendere la nostra sfera d'influenza in un attimo. Ecco, prendi qualcosina, oltre a esserti fatto nuovi amici qui ad Aerie Peak!", 0x6eb9a3b3, 0x0979fe95, 0x047d59fd, 0xf3a93aaa, 0x8efbe603, "....." },
  [2880] = { "Taglia sulle collane dei troll", "Porta $N1 Troll Tribal Necklaces a Fraggar Thundermantle, ad Aerie Peak.", "Mettitelo in testa, {race}: noi non facciamo parte dell'Alleanza! I Wildhammer sono indipendenti e si affidano alle imprese e alle azioni per dimostrare il proprio valore, non alle chiacchiere di chi usa le parole per gonfiare la propria inerzia!\n\nSe cerchi amici qui, dimostraci prima il tuo valore! I troll immondi che infestano le colline delle Hinterlands a volte portano collane tribali. Portamene cinque e lo segneremo come un passo nella giusta direzione per te.", "Voglio cinque di quelle collane tribali che portano addosso i troll. Se serve spiegarlo meglio, uccidendone uno hai buone probabilità di ottenerne una!\n\nDimostra il tuo valore ai Wildhammer!", "Così si parla! Vedi, queste collane dimostrano che sei disposto a sporcarti le mani. Noi Wildhammer apprezziamo questo in chi frequentiamo.\n\nContinua così e finirai per entrare nelle nostre grazie.", 0x53d7f0f7, 0xace2f057, 0x03782ded, 0xc50f9dc0, 0x7300fcde, "....." },
  [2922] = { "Salva il cervello di Techbot!", "Porta il Techbot's Memory Core al Tinkmaster Overspark, a Ironforge.", "Quando la nostra amata città di Gnomeregan cadde, una scintilla vagante deve aver colpito la mia povera creazione, Techbot. Un tempo aiutava me e i miei colleghi con i suoi innumerevoli congegni e la sua scorta illimitata di informazioni, ma il suo cervello positronico si è polarizzato. Ora è negatronico... e i comportamenti di Techbot si sono invertiti. Vaga per Gnomeregan in preda alla frenesia!\n\nMa forse si può recuperare. Forse, se riesci a recuperare la memoria centrale di Techbot e a portarmela, potrò scoprire la causa della polarizzazione e riparare il mio povero Techbot.", "Hai trovato Techbot? Hai recuperato la sua memoria centrale??", "Oh, è magnifico! Grazie, {name}! Mi metto subito al lavoro!!\n\nPovero, povero Techbot... Non abbatterti. Ti ripareremo.\n\nOra, dove ho messo quella spina per la mia chiave girevole idro-cric...", 0x142b3f91, 0x989bf380, 0xa96aa51e, 0xa4a609b7, 0xbbc02495, "....." },
  [2923] = { nil, "Parla con il Tinkmaster Overspark, a Ironforge.", "Il Tinkmaster Overspark è molto turbato per la sorte della sua creazione meccanica, Techbot. Ricordo Techbot come uno strumento gentile e utile per gli gnomi, ma Overspark mi dice che si è guastato.\n\nMolto triste. Ma con un po' di fortuna forse si può riparare!\n\nParla con il Tinkmaster Overspark, a Tinker Town, a Ironforge. Accoglierà volentieri il tuo aiuto.", nil, "Sì, è vero. Techbot si è ribellato, peggio di un ladro! Ti prego, puoi aiutarmi?", nil, 0x98ca0fa7, 0x226d20ab, nil, 0x8a6b241a, "m..m." },
  [2924] = { nil, "Porta $N1 Essential Artificials a Klockmort Spannerspan, a Ironforge.", "Un componente meccanico quasi universale, l'essential artificial, era di grande utilità per gli inventori e i fabbri di Gnomeregan. Ma durante la frenetica fuga dalla nostra città nessuno si è ricordato di portarne via qualcuno! E me ne serve una grossa scorta per un lavoro che intraprenderò presto.\n\nTi prego, va' a Gnomeregan e procurami qualche essential artificial. Li troverai nelle zone più profonde della città, custoditi in contenitori chiamati estrapolatori artificiali.\n\nGrazie, {name}, e fai presto!", "Hai gli essential artificial?", "Ce li hai! Ora posso cominciare i miei nuovi esperimenti!\n\nNon so come ringraziarti, {name}! Il tuo coraggio ha fatto fare alla ricerca gnomesca un balzo da gigante!", nil, 0x3bb3394a, 0xf08a62a3, 0x88153ec4, 0x0a9e26a6, "m...." },
  [2925] = { "L'essenziale di Klockmort", "Parla con Klockmort Spannerspan, a Ironforge.", "Un amico gnomo, Klockmort Spannerspan, mi ha scritto da Ironforge. Mi dice che ha bisogno di aiuto per una missione pericolosa ma essenziale a Gnomeregan, la città un tempo grandiosa degli gnomi, ora contaminata e piena di gnomi impazziti e dei loro congegni.\n\nIo devo restare qui, ma il cuore mi duole al pensiero di non aiutare il mio amico. Se puoi andare al posto mio, ti sarò molto debitrice.\n\nTrovi Klockmort a Tinkertown, a Ironforge.", nil, "Sì! Sì che mi serve aiuto per una missione a Gnomeregan. E tu, {class}, sei proprio quello che fa al caso mio!", 0xd1472bfc, 0x7fe3166f, 0x3f0bf57e, nil, 0x578dfce4, "...m." },
  [2926] = { nil, "Usa l'Empty Leaden Collection Phial su Irradiated Invader o Irradiated Pillager per raccogliere ricaduta radioattiva. Una volta piena, riportala a Ozzie Togglevolt, a Kharanos.", "Dopo l'incidente, Gnoarn non pensa e non parla d'altro che di ripulire Gnomeregan dall'infestazione di trogg e di trovare una cura per la malattia che la affligge, {name}.\n\nPer fortuna, Razzle e io siamo vicini a una specie di cura... oppure alla ricetta di un rum davvero potente. Non lo sapremo finché non lo proviamo! Naturalmente, per verificare la nostra teoria ci serviranno alcune cose, ovvero la ricaduta radioattiva dei trogg irradiati di Gnomeregan. Riempi questa fiala di bagliore verde e riportala!", "Non vedi che qui stiamo cercando di curare un'intera specie di gnomi??! Ci serve altro bagliore verde!", "Ottimo lavoro! È giunto il momento di provare la nuova formula. Se funziona, non solo dovrebbe guarire quello gnomo lebbroso catturato, ma dovrei anche ritrovarmi con una chioma folta! State indietro!", nil, 0xdf69f0fb, 0xa76f5528, 0x20727b89, 0x9b4aacb0, "m...." },
  [2927] = { "Il giorno dopo", "Parla con Ozzie Togglevolt, a Kharanos.", "Non penserai che io sia sempre stato calvo, vero? No, <signore/signora>! È stata la fuga di radiazioni a Gnomeregan a causarmi questa tragica perdita di capelli. Prima di quel giorno avevo l'unica gnomo-afro di tutta Azeroth.\n\n<Gnoarn agita il pugno in aria.>\n\nMaledetti quei maledetti trogg sudici: maledetti tutti!!\n\nForse non è troppo tardi, {name}. Possiamo ancora salvarla... la città, intendo! Parla con Ozzie Togglevolt, a Kharanos. Lui e il suo socio Razzle stanno lavorando a una soluzione.", nil, "Pensavo che la perdita di quella splendida chioma sarebbe stata la sua fine, e invece è sopravvissuto!\n\nEro proprio accanto a lui quando è stato colpito dal dardo di radiazioni. Quelle deliziose ciocche castane sono cadute a terra a ciuffi! A grappoli! L'orrore è stato solo peggiorato quando Gnoarn è andato completamente fuori di testa! Oh sì, fuori di testa, ti dico! Gnoarn si è toccato la testa calva incredulo, e lo sguardo nei suoi occhi gridava vendetta, {name}! Poi ha rivolto la sua rabbia contro i trogg!\n\n<Ozzie rabbrividisce.>", 0xf43f453e, 0xba99320a, 0x80d33f0e, nil, 0xbb58d6a8, "...m.", nil, nil, 0xb6251687, nil, nil },
  [2928] = { "Gyrodrillmatic Excavationator", "Porta ventiquattro Robo-mechanical Guts a Shoni, a Stormwind.", "È terribile, {name}. Non avremo abbastanza pezzi per portare la nostra flotta di gyrodrillmatic excavationator fino a Dun Morogh.\n\nCi servono pezzi di ricambio, {name}. Quale posto migliore di Gnomeregan per trovare i pezzi di ricambio per i nostri veicoli? Ho sentito che là dentro robot e mech girano come bestiame al pascolo.\n\nHo bisogno che tu vada a Gnomeregan e faccia a pezzi quei robot. Riportami le loro budella robotiche. Due dozzine dovrebbero bastare.", "Se fosse una gara, a quest'ora avresti già perso.", "Andrà benissimo, {name}. Un gyrodrillmatic excavationator riparato; ne restano 398.", 0x7c11ff31, 0x78ec2936, 0x740676eb, 0x3fc85274, 0xaf06627a, "....." },
  [2929] = { "Il grande tradimento", "Avventurati a Gnomeregan e uccidi il Mekgineer Thermaplugg. Torna dall'High Tinker Mekkatorque quando hai finito.", "Mi fidavo di Thermaplugg, {race}. Mai mi sarei aspettato che tradisse me e l'intero popolo gnomesco. E per cosa? Potere? Ricchezza? Tutte cose che col tempo avrebbe avuto. Ora siamo stati cacciati dalla nostra casa e quel pazzo ne è al comando. Il re del nulla...\n\nRiprenderemo Gnomeregan, {name}. Non ci fermeremo finché la città non sarà di nuovo sotto il nostro controllo. Se vuoi unirti alla nostra lotta, ti chiedo un compito semplice: uccidi il traditore. Distruggi il Mekgineer Thermaplugg.", "Il compito è compiuto? Ha implorato clemenza? Pietà??", "Mi piace pensare che l'ultima cosa che gli è passata per la testa mentre crollava a terra sia stato il tuo piede, {race}. Con Thermaplugg morto, i nostri piani per riprendere Gnomeregan sono un passo più vicini a diventare realtà.", 0xc7223d52, 0xfb52e324, 0x8bff6fc1, 0xada3365b, 0x5ff1117b, "....." },
  [2930] = { "Recupero dati", "Porta una Prismatic Punch Card al Master Mechanic Castpipe, a Ironforge.", "Quando siamo fuggiti da Gnomeregan abbiamo lasciato indietro un sacco di dati! Dati di vitale importanza!\n\nMi servono i dati su una prismatic punch card, da un terminale ad alta sicurezza Matrix Punchograph 3005-D, nel profondo di Gnomeregan. Devi accedere al terminale, ma per farlo ti serve prima un'autorizzazione... e per averla devi accedere ai terminali a sicurezza più bassa, i modelli -A, -B e -C. E per fare questo ti servono le schede perforate di sicurezza, a cominciare da quella bianca... e abbiamo lasciato tutte le schede in città.\n\nÈ una catastrofe! Puoi aiutarci?", "Hai la prismatic punch card??", "Ce l'hai fatta! Hai trovato la prismatic punch card e recuperato i dati perduti! Dati vitali, cruciali, incommensurabilmente importanti, senza i quali non potevamo vivere un momento di più!\n\nIl tuo servizio agli gnomi sarà ricordato a lungo, {name}.", 0xb572ead8, 0x0d6cb3dd, 0x5be7a1ee, 0xa5d0b260, 0x9a4bbb5a, "....." },
  [2931] = { "L'incarico di Castpipe", "Parla con il Master Mechanic Castpipe, a Ironforge.", "Il Master Mechanic Castpipe, a Ironforge, ha bisogno di avventurieri! Sta organizzando gruppi per rientrare a Gnomeregan in una missione di recupero dati di massima segretezza e importanza.\n\nCastpipe non sarà membro dell'Enlightened Assembly of Arcanology, Alchemy and Engineering Sciences come me, ma è comunque uno gnomo intelligente, quindi se pensa che sia importante, secondo i miei calcoli c'è un ottantaquattro per cento di probabilità che lo sia davvero!\n\nSono buone probabilità!", nil, "Sto organizzando missioni di estrazione dati a Gnomeregan. Se sei qui per questo, ascolta bene!", 0x95ff10c3, 0x3809bbd3, 0x4d68d41f, nil, 0x3d0d0c09, "...m." },
  [2940] = { nil, "Chiedi a Daryn Lightwind se puoi prendere in prestito il suo libro.", "Sembra che nessuno apra questo libro da moltissimo tempo. Le copertine sono consumate e le pagine ingiallite, ma esaminandolo noti che potrebbe essere proprio quello che Troyas cerca.\n\nLo prendi, ma ti rendi conto che forse dovresti chiedere prima di prenderlo in prestito.", nil, "Allora vorresti prendere in prestito Feralas: A History?\n\nFammi pensare...\n\nTi presterò questo libro, {name}, ma solo se prima farai una cosa per me.", nil, 0xcddd8fc5, 0xe6f4dd42, nil, 0x5487bf1c, "m..m." },
  [2941] = { "Il prestito", "Porta la lettera a Curgle Cranklehop, a Tanaris.", "Ho studiato molti argomenti nella mia vita, e la mia ultima passione sono gli snapjaw che occupano la spiaggia degli Hinterlands. Ce n'è uno in particolare che vorrei vedere, uno snapjaw gigante di nome Gammerita. Vorrei andarci io, ma le mie ricerche mi trattengono qui. Credo che una sua immagine sarebbe la cosa migliore dopo vederla di persona.\n\nPorta questa lettera a Curgle Cranklehop, a Tanaris. Ha creato per me un'invenzione che sa catturare un'immagine. L'ha chiamata \"istantanea\", mi pare...", "Una lettera... per me?", "Sei <un/una> <altro/altra> degli stagisti di Daryn? È una storica molto preparata, {name}. Dovresti essere <grato/grata> di studiare sotto la sua guida.\n\nOra, fammi prendere il Super Snapper FX. Ti piacerà da morire!", 0xbf91965a, 0x1d265812, 0x87f31ae2, 0x84f49355, 0x65e2b535, "....." },
  [2943] = { "Ritorno da Troyas", "Consegna il libro a Troyas Moonbreeze, a Feathermoon Stronghold.", "Eccolo, {name}. Ti prego, abbi cura del mio libro.\n\nOra vai, presto. Di sicuro Troyas non vede l'ora che tu torni.", "Salve, {name}. Sei <stato/stata> a Darnassus?", "Hai portato un libro. Eccellente!", 0xff5baae2, 0xcfcf05ac, 0xb4df8e98, 0x38e98959, 0xab1081ea, "....." },
  [2946] = { "Vedere cosa succede", "Porta i dischi di platino in miniatura ai cancelli di Uldum, a Tanaris, e cerca indizi sul legame tra i due.", "Vogliamo che porti i dischi in miniatura che hai trovato ai cancelli sigillati di Uldum. Non... non sappiamo cosa succederà quando lo farai.\n\nSembra rischioso, certo, lo ammettiamo. Potrebbe però non succedere nulla. Potresti dover usare i dischi su qualcosa. Forse le porte si sbloccano quando hai i dischi con te. Sii <pronto/pronta> a provare di tutto, e <pronto/pronta> a qualsiasi cosa accada.\n\nQuando avrai scoperto cosa succede, torna a Ironforge. Avremo un sacco di cose da analizzare quando avrai finito!", "Questo piedistallo dall'aspetto familiare spunta dalla sabbia rovente. Forse la sua presenza qui significa qualcosa...", "Quando tocchi il piedistallo, i dischi in miniatura di Uldaman ronzano e brillano nel tuo zaino. Una sensazione di formicolio familiare ti percorre le mani, mentre l'immagine di un altro Stone Watcher prende vita davanti ai cancelli di Uldum.\n\n\"Saluti. Sono un guardiano dell'accesso. Ai dischi usati per l'accesso mancano i dischi d'ingresso corretti, le Plates of Uldum. Si prega di integrare queste piastre nella struttura dei dischi e di ripetere la sequenza d'accesso. Grazie.\"", 0x7446c0c8, 0xec67bdb9, 0x5f1b449a, 0xd9076687, 0x2a4c8eea, "....." },
  [2947] = { "Il ritorno dell'anello", "Puoi tenere l'anello, oppure trovare il responsabile dell'impronta e delle incisioni all'interno della fascia.", "Aprendo la scatola prodotta dallo Sparklematic 5200 trovi ciò che sospettavi: un anello lucente! Indossandolo, senti un'ondata di potere magico attraversarti il corpo.\n\nAll'interno della fascia c'è una piccola ma riconoscibile impronta del sigillo di Ironforge. Accanto sono incise tre piccole iniziali: \"TdK\". Potrebbero essere le iniziali del precedente proprietario, o forse quelle dell'artigiano dell'anello. Tenere l'anello... o restituirlo a questa persona. Decisioni, decisioni...", "Ehi, calma, socio: sono un uomo d'affari molto importante! Sono sicuro che il corriere è solo in ritardo con la consegna dell'affitto... aspetta... tu non sei il mio padrone di casa.\n\nMa certo che no, che sciocco! Sei <venuto/venuta> a cercare il miglior gioielliere di tutta Ironforge, uno che non crea oggetti maledetti! Sì!\n\nEhm... di cosa hai bisogno?", "Un anello, dici? Vediamo... sì, perbacco, quell'anello l'ho fatto io.\n\nPrima che Gnomeregan saltasse in aria avevo una piccola bottega lì. Forse è uno di quelli che ho lasciato quando me la sono data a gambe; è un disegno semplice, e ne ho fatti diversi simili. Magari è di qualcuno che non ce l'ha fatta.\n\nCe l'avevano i nani Dark Iron? Be', questo aggiunge un nuovo strato di complotto ai nove che già circolano. Forse alle autorità interesserebbe saperlo; con uno come me è sprecato.\n\nOra, torniamo all'anello...", 0x9b2297a2, 0x8cbc1bad, 0x463d3a78, 0xf03132b6, 0x9157f220, "....." },
  [2948] = { "Miglioria gnomesca", "Porta il Brilliant Gold Ring, un Silver Bar, una Moss Agate e $N1 monete d'argento a Talvash del Kissel, a Ironforge.", "Senti, {name}, quell'anello è tuo, certo... ma posso fartene uno migliore! Quel disegno, come ho detto, è davvero semplice. Ora sono molto più abile, e per la modica cifra di trenta monete d'argento te lo rimetto a nuovo! Be', un po' più di trenta, in realtà...\n\nSono un po' in difficoltà adesso: le mie scorte di materiali sono esaurite. Se mi porti un lingotto d'argento e un'agata muschiata, aggiungerò all'anello un intreccio d'argento e agata che gli darà un tocco in più!\n\nFidati di me!", "Hai i materiali che mi servono? Non te li chiederei se non fossi in un periodo sfortunato...", "Ah, proprio quello che mi serviva! Un giorno, quando sarò uscito da questo buco in cui mi trovo ingiustamente, creerò per te, per tutti, i ninnoli più belli di tutta Azeroth! Fino ad allora, grazie per essere <stato/stata> così <sportivo/sportiva> con i materiali. Di solito chiederei dieci volte tanto per un anello di questa qualità...\n\nA proposito di anelli, ecco il tuo nuovo!", 0xaf868c64, 0x0fd2ffb2, 0x8547b93f, 0x965ed2bb, 0xd8803d0d, "....." },
  [2949] = { "Il ritorno dell'anello", "Puoi tenere l'anello, oppure trovare il responsabile dell'impronta e delle incisioni all'interno della fascia.", nil, nil, nil, 0x9b2297a2, 0x8cbc1bad, nil, nil, nil, "..mmm" },
  [2962] = { "L'unica cura è altro bagliore verde", "Recati a Gnomeregan e riporta della High Potency Radioactive Fallout. Attenzione: la ricaduta è instabile e decade piuttosto in fretta.\n\nAl termine del compito Ozzie avrà bisogno anche della tua Heavy Leaden Collection Phial.", "Il tuo campione non solo era insufficiente per quantità, ma anche impuro.\n\nCi serve altro bagliore verde. Evidentemente i trogg non sono abbastanza irradiati per le nostre esigenze. Dovrai entrare a Gnomeregan e riportare della ricaduta radioattiva direttamente dalla fonte. Parlo delle melme, degli acquattati e degli orrori irradiati. Attenzione: contenere questo tipo di ricaduta è difficile. Potrebbero servirti diversi tentativi con la fiala prima di recuperare un campione adatto.", "Mm, non stai brillando. È un buon segno.", "<Ozzie ti esamina.> Notevole, hai ancora tutti gli arti. Ora vediamo cosa sa fare questa roba!", 0xc891dea0, 0x4e7ea0ad, 0x6fc2256f, 0x66e8e057, 0x6eeec372, "....." },
  [2963] = { "Presagi di Uldum", "Parla con lo Historian Karnik nella Hall of Explorers di Ironforge.", "Salute di nuovo, {name}! La tua scoperta a Uldaman ha messo in fermento l'Explorers' League. La lega sta lavorando per svelare i segreti dei dischi di platino in miniatura che hai trovato. Il tuo fortunato arrivo qui nella Hall mi permette di dirti che forse siamo su una pista interessante!\n\nLo Historian Karnik ha scoperto indizi importanti sulle vere origini della Valley of the Watchers, nel deserto di Tanaris. Vorrebbe parlarti il prima possibile!", nil, "Sono lieto che il tuo interesse per l'esplorazione non si spenga, {name}! Con il tuo talento naturale e la tua grinta potremmo svelare segreti che non pensavamo possibili!\n\nI Discs of Norgannon a Uldaman erano un archivio di informazioni vastissimo; ti è stato permesso di accedere solo agli strati superiori, per così dire, delle informazioni lì custodite. Si dice che i creatori avessero altri archivi sparsi per Azeroth. E questo ci porta a Uldum...", 0xb4588354, 0x552c0a0b, 0x0dfef97f, nil, 0xbb6292ae, "...m." },
  [2964] = { "Un compito futuro", "Parla con l'High Explorer Magellas a Ironforge.", "Be', {name}... sembra che per il momento siamo a un vicolo cieco. Sappiamo cosa ci serve, le Plates of Uldum, ma non abbiamo idea di dove possano trovarsi. Dovremo fare parecchie ricerche per elaborare un piano d'azione solido. Ho un paio di idee su dove cominciare a cercare; spero proprio che presto ti chiederemo di partire a recuperarle.\n\nL'High Explorer deve esserne informato, {name}; senza dubbio vorrà anche ringraziarti di persona per aver aiutato ancora una volta la lega.", nil, "Siamo tutti d'accordo, allora: il miglior piano d'azione è sospendere tutto finché non avremo ristretto le zone in cui queste piastre potrebbero essere nascoste. Ci hai portato fin qui, {name}, e spero che sarai tu a tornare sul campo per aprire Uldum per tutti noi!\n\nNel frattempo permettimi di darti questo compenso; dovrebbe coprire le spese che hai sostenuto per aiutarci, più un piccolo extra. Torna presto a trovarci... Uldum ci chiama!", 0xa21b81b7, 0x886ee345, 0xf6da6a06, nil, 0xa20f123f, "...m." },
  [2965] = { "Presagi di Uldum", nil, nil, nil, nil, 0xb4588354, nil, nil, nil, nil, ".mmmm" },
  [2966] = { "Vedere cosa succede", "Porta i dischi di platino in miniatura ai cancelli di Uldum, a Tanaris, e cerca indizi sul legame tra i due.", nil, "Questo piedistallo dall'aspetto familiare spunta dalla sabbia rovente. Forse la sua presenza qui significa qualcosa...", "Quando tocchi il piedistallo, i dischi in miniatura di Uldaman ronzano e brillano nel tuo zaino. Una sensazione di formicolio familiare ti percorre le mani, mentre l'immagine di un altro Stone Watcher prende vita davanti ai cancelli di Uldum.\n\n\"Saluti. Sono un guardiano dell'accesso. Ai dischi usati per l'accesso mancano i dischi d'ingresso corretti, le Plates of Uldum. Si prega di integrare queste piastre nella struttura dei dischi e di ripetere la sequenza d'accesso. Grazie.\"", 0x7446c0c8, 0xec67bdb9, nil, 0xd9076687, 0x2a4c8eea, "..m.." },
  [2968] = { "Un compito futuro", nil, nil, nil, nil, 0xa21b81b7, nil, nil, nil, nil, ".mmmm" },
  [2983] = { "Il richiamo del fuoco", nil, nil, nil, nil, 0x53f3b76b, nil, nil, nil, nil, ".mmmm" },
  [2984] = { "Il richiamo del fuoco", nil, nil, nil, nil, 0x53f3b76b, nil, nil, nil, nil, ".mmmm" },
  [2985] = { "Il richiamo dell'acqua", "Trova Islen Waterseer nelle Barrens.", "Sembri <pronto/pronta> per la tua prossima prova, {name}. Sei <stato/stata> paziente nei tuoi studi, ma è giunto il momento di imparare di più. È giunto il momento di imparare la purezza dell'acqua.\n\nCerca Islen Waterseer nelle Barrens. Si trova lungo la costa orientale, a sud del Southfury River e di Ratchet. La troverai lì, nella sua capanna da pesca. Buona fortuna, {name}.", nil, "Il vento ti raggiunge rapido dall'orizzonte; la terra è salda sotto i tuoi piedi; e il tuo spirito è già scaldato dal fuoco. Direi che è tempo che tu impari la purezza dell'acqua.\n\nIl tuo cammino ti ha portato fin qui, e il tuo spirito ti darà la forza di proseguire ancora oltre. Ma il primo passo spetta a te.", 0x1f0e11aa, 0x52f30fbd, 0x2f9a1a5e, nil, 0xf9228c66, "...m." },
  [2986] = { "Il richiamo dell'acqua", "Trova Islen Waterseer nelle Barrens.", nil, nil, "Il vento ti raggiunge rapido dall'orizzonte; la terra è salda sotto i tuoi piedi; e il tuo spirito è già scaldato dal fuoco. Direi che è tempo che tu impari la purezza dell'acqua.\n\nIl tuo cammino ti ha portato fin qui, e il tuo spirito ti darà la forza di proseguire ancora oltre. Ma il primo passo spetta a te.", 0x1f0e11aa, 0x52f30fbd, nil, nil, 0xf9228c66, "..mm." },
  [2988] = { "Le gabbie dei Witherbark", "Controlla le gabbie nei due villaggi Witherbark, poi torna dal Gryphon Master Talonaxe.", "Il figlio del nostro grifone più possente è scomparso! L'erede di Swiftwing, Sharpbeak, si è perso qualche giorno fa mentre cacciava con i genitori, e crediamo che siano stati i troll a prenderlo.\n\nDevi aiutarci! Controlla le gabbie nei due villaggi dei troll Witherbark per vedere se Sharpbeak è lì.", "Hai controllato le gabbie, {name}? Dobbiamo trovare Sharpbeak!", "Sharpbeak non era nei villaggi? Uhm... sono brutte notizie. Quel grifone è destinato a guidare la prossima generazione di grifoni. Se va perduto, la forza e lo spirito della nostra flotta ne soffriranno enormemente.", 0xd2ed808e, 0x7500a89e, 0x0bd1ca1e, 0xc6517c8f, 0xae95575d, "....." },
  [2989] = { "L'Altar of Zul", "Controlla la cima dell'Altar of Zul, poi torna dal Gryphon Master Talonaxe.", "Sharpbeak non era con i troll Witherbark. Forse l'hanno preso i troll Vilebranch. Va' all'Altar of Zul, al margine occidentale del territorio Vilebranch, e cerca il piccolo di grifone.", "Sbrigati, {name}! Se Sharpbeak ce l'hanno i troll Vilebranch, chissà cosa gli stanno facendo!", "Sharpbeak non c'era? È una brutta notizia, ma anche una buona...\n\nÈ un bene che non fosse all'Altar of Zul, perché i troll Vilebranch sono noti per i loro sacrifici.\n\nTi ringrazio per tutto il tuo aiuto, ma temo che ci aspetti un compito ancora più grande.", 0x17765c2d, 0x87ae2e16, 0x8dc2c1ee, 0xa11ece19, 0x348c2bb1, "....." },
  [2990] = { nil, "Porta la Sharpbeak's Feather a Thadius Grimshade, nelle Blasted Lands.", "Porta questa piuma a Thadius Grimshade, il divinatore. Ha lasciato Aerie Peak anni fa per inseguire conoscenze più oscure, ma nel suo cuore è ancora un Wildhammer!\n\nE forse i suoi talenti possono aiutarci a trovare Sharpbeak.\n\nQuesta piuma è stata presa dal nido dove dorme il piccolo di grifone. Se la dai a Thadius, con un po' di fortuna potrà usare la sua magia divinatoria per trovare Sharpbeak.\n\nBuona fortuna, {name}. Troverai Thadius nelle Blasted Lands, nella torre dei maghi della Nethergarde Keep.", "{name}, porti un dono?", "Ah, sì. Questa piuma appartiene a un bel grifone. Uno destinato a grandi cose... se riesce a diventare adulto senza danni.\n\nVuoi trovarlo? Allora ascolta bene, valoroso {class}...", nil, 0xf32d217d, 0x7a4689be, 0x0c71e9f6, 0xe9dbc04a, "m...." },
  [2991] = { nil, "Porta il Nekrum's Medallion a Thadius Grimshade, nelle Blasted Lands.", "Scoprirò dov'è il tuo grifone, ma prima devi fare qualcosa per me. C'è un troll a Zul'Farrak, Nekrum Gutchewer, che possiede un medaglione che vorrei tanto studiare. Portami quel medaglione e userò i miei poteri per trovare Sharpbeak.\n\nZul'Farrak si trova oltre l'oceano, a ovest, nel deserto di Tanaris.", "Hai il Nekrum's Medallion, {name}? Ci sono poteri nascosti al suo interno che non vedo l'ora di scoprire.", "Ah, il medaglione di Nekrum. Si dice che abbia dato al troll una vita innaturalmente lunga, ma a caro prezzo. Spero di scoprire un modo per sfruttarne il potere evitando i suoi... sgradevoli effetti collaterali.\n\nMi hai reso un servizio, {name}. Ora manterrò la mia parte del patto.", nil, 0x69d044e5, 0x23900882, 0xb6e9fb8f, 0x5ceb3a7c, "m...." },
  [2992] = { "La divinazione", "Aspetta che Grimshade compia il rituale di divinazione.", "Fammi spazio mentre compio un rituale di divinazione. Troverò il legame tra la piuma che mi hai portato e il suo proprietario, e seguirò quel legame fino a Sharpbeak.\n\nCioè... lo farò se tutto va secondo i piani. Altrimenti... faresti meglio a chiudere gli occhi.", nil, "Il rituale è riuscito. Ho visto Sharpbeak e posso dirti come trovarlo.", 0xf42df580, 0xa6313eaf, 0x9aae3f04, nil, 0xd58e9db1, "...m." },
  [2993] = { "Ritorno nelle Hinterlands", "Parla con il Gryphon Master Talonaxe.", "Sharpbeak è tenuto in una gabbia, in alto su una rupe in cima a Jintha'Alor, nelle Hinterlands. La chiave di questa gabbia è in possesso dell'alta sacerdotessa dei troll Vilebranch, la Vile Priestess Hexx.\n\nEcco. Ho fatto la mia parte. Ti auguro buona fortuna nella tua impresa, {name}.", nil, "Hai parlato con Grimshade? Cosa ha detto?\n\n...Cosa? Sharpbeak ce l'hanno i troll Vilebranch? È insopportabile! Dobbiamo organizzare una forza per riprenderlo!", 0x5419b47b, 0x4ba254df, 0x0fa70323, nil, 0x98f33a86, "...m." },
  [2994] = { "Salvare Sharpbeak", "Fatti strada fino alla cima di Jintha'Alor, uccidi la Vile Priestess Hexx per avere la chiave della gabbia di Sharpbeak e salva Sharpbeak.", "Dobbiamo salvare Sharpbeak!\n\nFatti strada fino alla cima di Jintha'Alor, nel cuore del territorio Vilebranch, prendi la chiave della gabbia di Sharpbeak dalla perfida sacerdotessa Hexx, poi trova e salva Sharpbeak!", "Salva Sharpbeak!", "Swiftwind e Keenclaw sono tornati con il loro piccolo poco fa, e gli stanno addosso come genitori novelli. Vederli di nuovo insieme basta a far luccicare gli occhi anche a questo vecchio nano...\n\nNon potremo mai ripagarti abbastanza per ciò che hai fatto, {name}. I grifoni di Aerie Peak e i loro cavalieri canteranno il tuo nome per molto, molto tempo.", 0x64daaa65, 0x7af19d1c, 0x68d07569, 0x180edb9f, 0x5cb3cadc, "....." },
  [2996] = { "Alla ricerca di Strahad", "Parla con Strahad Farsan, a Ratchet.", nil, nil, nil, 0x884bfbbe, 0x0c866240, nil, nil, nil, "..mmm" },
  [2997] = { nil, "Parla con Tiza Battleforge, a Ironforge.", "Salve, {name}. So che sei <impegnato/impegnata> ad aiutare la gente di Dun Morogh, ma quando avrai tempo dovresti salire a Ironforge per parlare con una delle nostre più rispettate: Tiza Battleforge. È da lei che vanno i paladini più giovani quando è tempo di imparare di più sulla Luce e su ciò che ci si aspetta da loro.\n\nLa trovi al piano di sopra, nella Hall of Mysteries. Se non ci sei mai <stato/stata>, è nel Mystic Ward. Buona fortuna, {name}.", nil, "Ben <trovato/trovata>, {name}. Spero che la Luce ti mostri il vero cammino e ti protegga dal male.", nil, 0x04be03fc, 0x4e98a6c9, nil, 0x942f654d, "m..m." },
  [2998] = { nil, "Parla con Duthorian Rall, a Stormwind.", "Salute, <fratello/sorella>. Duthorian Rall, uno dei nostri paladini più influenti, parlava di te di recente. L'ho sentito dire che è ora di metterti alla prova... insieme a parole molto lusinghiere su come te la sei cavata finora.\n\nSe fossi in te, andrei a Stormwind a parlargli appena hai tempo. Di sicuro è nella Cathedral of Light: è lì che passa quasi tutto il suo tempo.", nil, "È bello qui a Stormwind, non trovi?\n\nNon potevi arrivare in un momento migliore, {name}.", nil, 0x0f3ca705, 0x35944d83, nil, 0x3fd2197e, "m..m.", nil, nil, 0xa8a5e826, nil, nil },
  [2999] = { nil, nil, nil, nil, "Ben <trovato/trovata>, {name}. Spero che la Luce ti mostri il vero cammino e ti protegga dal male.", nil, nil, nil, nil, 0x942f654d, "mmmm." },
})
